function logoutProfile(){profile.email='';localStorage.removeItem(LS+'email');closeModal();gold('Çıkış yapıldı.');render()}
function openCatManager(){const list=categories().filter(c=>c!=='ALL').map(c=>`<option value="${escAttr(c)}">${esc(catName(c))}</option>`).join(''); openModal('Kategori yönetimi',`<div class="formGrid"><label>Yeni kategori<input id="newCat" placeholder="Kategori adı"></label><button onclick="addCategory()">Kategori ekle</button><label>Mevcut kategori<select id="catManage">${list}</select></label><label>Yeni ad<input id="renameCat" placeholder="Yeni kategori adı"></label><button class="ghost" onclick="renameCategory()">Ad değiştir</button><button class="danger" onclick="removeCategory()">Kategori kaldır</button></div>`)}
function addCategory(){const n=$('newCat').value.trim(); if(!n)return gold('Kategori adı boş olamaz.'); const c=customCats(); if(!c.includes(n))c.push(n); setJSON('customCats',c); closeModal(); gold('Kategori eklendi.'); render()}
function renameCategory(){const old=$('catManage').value, neu=$('renameCat').value.trim(); if(!old||!neu)return gold('Kategori ve yeni ad gerekli.'); confirmAction('Kategori adı değişsin mi?',catName(old)+' → '+neu,()=>{const a=aliases();a[old]=neu;setJSON('catAliases',a);closeModal();render();gold('Kategori adı değiştirildi.')})}
function removeCategory(){const c=$('catManage').value; confirmAction('Kategori kaldırılsın mı?',catName(c)+' gizlenecek; özel verileri varsa kaldırılacak.',()=>{let h=Array.from(hiddenCats()); if(!h.includes(c))h.push(c); setJSON('hiddenCats',h); setJSON('customWords',customWords().filter(w=>w.cat!==c)); setJSON('customSources',customSources().filter(s=>sourceCat(s)!==c)); if(settings.cat===c)settings.cat='ALL'; closeModal(); render(); gold('Kategori kaldırıldı.')})}
function openTextManager(){const list=categories().filter(c=>c!=='ALL').map(c=>`<option value="${escAttr(c)}">${esc(catName(c))}</option>`).join(''); openModal('Metin yükleme / çıkarma',`<div class="formGrid"><label>Kategori<select id="textCat">${list}</select></label><textarea id="bulkText" placeholder="Her satır: Hollandaca;Okunuş;İngilizce;Türkçe"></textarea><button onclick="importTextRows()">Metni kategoriye ekle</button><button class="danger" onclick="clearCategoryCustomText()">Bu kategorideki özel metni çıkar</button></div>`)}
function importTextRows(){const c=$('textCat').value, rows=$('bulkText').value.split(/\n+/).map(x=>x.trim()).filter(Boolean); if(!rows.length)return gold('Metin boş.'); confirmAction('Metin eklensin mi?',rows.length+' satır '+catName(c)+' kategorisine eklenecek.',()=>{const words=customWords(),src=customSources(); rows.forEach((r,i)=>{const p=r.split(/[;	,]/).map(x=>x.trim()); const nl=p[0]||''; if(!nl)return; const read=p[1]||'', en=p[2]||'', tr=p[3]||''; const id='CUS-'+Date.now()+'-'+i; words.push({id,cat:c,nl,read,en,tr,root:''}); src.push({id:id+'S',cat:c,source:c,ref:'Kullanıcı',nl,read,en,tr})}); setJSON('customWords',words); setJSON('customSources',src); closeModal(); applyFilter(); gold('Metin eklendi.')})}
function clearCategoryCustomText(){const c=$('textCat').value; confirmAction('Özel metin çıkarılsın mı?',catName(c)+' kategorisine eklediğiniz özel metinler silinir.',()=>{setJSON('customWords',customWords().filter(w=>w.cat!==c)); setJSON('customSources',customSources().filter(s=>sourceCat(s)!==c)); closeModal(); applyFilter(); gold('Özel metin çıkarıldı.')})}


/* --- File upload import for category text manager. Supports TXT/CSV/TSV and basic XLSX first-sheet import. --- */
function openTextManager(){
  const list=categories().filter(c=>c!=='ALL').map(c=>`<option value="${escAttr(c)}">${esc(catName(c))}</option>`).join('');
  openModal('Metin yükleme / çıkarma',`<div class="formGrid">
    <label>Kategori<select id="textCat">${list}</select></label>
    <label>Dosya yükle<input id="bulkFile" type="file" accept=".csv,.txt,.tsv,.xlsx,text/csv,text/plain,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" onchange="handleImportFile()"></label>
    <button class="ghost" onclick="handleImportFile()">📄 Seçilen dosyayı oku</button>
    <div id="fileImportStatus" class="goldNote">CSV, TXT, TSV veya XLSX seçebilirsiniz. Dosya okununca içerik aşağıdaki kutuya aktarılır; sonra kategoriye ekleyebilirsiniz.</div>
    <textarea id="bulkText" placeholder="Her satır: Hollandaca;Okunuş;İngilizce;Türkçe;Arapça;Arapça Okunuş;Rusça;Rusça Okunuş"></textarea>
    <button onclick="importTextRows()">Metni / dosyayı kategoriye ekle</button>
    <button class="danger" onclick="clearCategoryCustomText()">Bu kategorideki özel metni çıkar</button>
  </div>`)
}
function importDelimiter(line){
  const seps=[';','\t',',']; let best=';', bestCount=-1;
  seps.forEach(sep=>{let count=0,q=false; for(let i=0;i<String(line||'').length;i++){const ch=line[i]; if(ch==='"'){if(q&&line[i+1]==='"')i++; else q=!q} else if(!q&&ch===sep)count++} if(count>bestCount){best=sep;bestCount=count}});
  return best;
}
function parseDelimitedText(text){
  text=String(text||'').replace(/^\uFEFF/,'').replace(/\r\n/g,'\n').replace(/\r/g,'\n');
  const first=text.split('\n').find(x=>x.trim())||''; const sep=importDelimiter(first);
  const rows=[]; let row=[], cell='', q=false;
  for(let i=0;i<text.length;i++){
    const ch=text[i];
    if(ch==='"'){
      if(q&&text[i+1]==='"'){cell+='"'; i++} else q=!q;
    }else if(!q&&ch===sep){row.push(cell.trim()); cell='';
    }else if(!q&&ch==='\n'){row.push(cell.trim()); if(row.some(x=>String(x).trim()))rows.push(row); row=[]; cell='';
    }else cell+=ch;
  }
  row.push(cell.trim()); if(row.some(x=>String(x).trim()))rows.push(row);
  return normalizeImportRows(rows);
}
function normalizeImportRows(rows){
  rows=(rows||[]).map(r=>(r||[]).map(x=>String(x??'').trim())).filter(r=>r.some(Boolean));
  if(rows.length&&isImportHeader(rows[0]))rows=rows.slice(1);
  return rows.filter(r=>r[0]);
}
function isImportHeader(r){
  const joined=(r||[]).join(' ').toLocaleLowerCase('tr');
  return /hollandaca|nederlands|arapça|rusça|okunuş|okunus|ingilizce|türkçe|turkce/.test(joined)&&!/[a-zçğıöşüа-яء-ي]{2,}.*[;\t,]/i.test((r||[])[0]||'');
}
function csvEscapeCell(v){v=String(v??''); return /[;"\n\r\t,]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}
function rowsToSemicolonText(rows){return normalizeImportRows(rows).map(r=>r.map(csvEscapeCell).join(';')).join('\n')}
function setImportStatus(msg){const el=$('fileImportStatus'); if(el)el.textContent=msg; gold(msg)}
function handleImportFile(){
  const input=$('bulkFile'); const file=input&&input.files&&input.files[0];
  if(!file)return setImportStatus('Önce CSV, TXT, TSV veya XLSX dosyası seçin.');
  const name=(file.name||'dosya').toLowerCase();
  if(name.endsWith('.xlsx')){readXlsxImportFile(file); return}
  const reader=new FileReader();
  reader.onerror=()=>setImportStatus('Dosya okunamadı.');
  reader.onload=()=>{const text=String(reader.result||''); const rows=parseDelimitedText(text); $('bulkText').value=rowsToSemicolonText(rows); setImportStatus((file.name||'Dosya')+' okundu: '+rows.length+' satır hazır.');};
  reader.readAsText(file,'utf-8');
}
function importTextRows(){
  const cat=$('textCat').value, rows=parseDelimitedText($('bulkText').value);
  if(!rows.length)return gold('Metin veya dosya içeriği boş.');
  confirmAction('Metin eklensin mi?',rows.length+' satır '+catName(cat)+' kategorisine eklenecek.',()=>importParsedRows(cat,rows));
}
function importParsedRows(cat,rows){
  const words=customWords(), src=customSources(), now=Date.now(); let added=0;
  normalizeImportRows(rows).forEach((p,i)=>{
    const nl=p[0]||''; if(!nl)return;
    const read=p[1]||'', en=p[2]||'', tr=p[3]||'', ar=p[4]||'', ar_read=p[5]||'', ru=p[6]||'', ru_read=p[7]||'';
    const id='CUS-'+now+'-'+i;
    const item={id,cat,nl,read,en,tr,ar,ar_read,ru,ru_read,root:''};
    words.push(item); src.push({id:id+'S',cat,source:cat,ref:'Kullanıcı',nl,read,en,tr,ar,ar_read,ru,ru_read}); added++;
  });
  setJSON('customWords',words); setJSON('customSources',src); closeModal(); applyFilter(); gold(added+' satır kategoriye eklendi.');
}
async function readXlsxImportFile(file){
  try{
    const rows=await xlsxFirstSheetRows(await file.arrayBuffer());
    const normalized=normalizeImportRows(rows);
    $('bulkText').value=rowsToSemicolonText(normalized);
    setImportStatus((file.name||'Excel')+' okundu: '+normalized.length+' satır hazır.');
  }catch(e){
    setImportStatus('XLSX okunamadı. Bu cihaz desteklemiyorsa dosyayı CSV olarak kaydedip yükleyin. Hata: '+(e&&e.message?e.message:e));
  }
}
function readU16(dv,off){return dv.getUint16(off,true)}
function readU32(dv,off){return dv.getUint32(off,true)}
async function unzipXlsx(buffer){
  const bytes=new Uint8Array(buffer), dv=new DataView(buffer), dec=new TextDecoder('utf-8');
  let eocd=-1; for(let i=bytes.length-22;i>=Math.max(0,bytes.length-66000);i--){if(readU32(dv,i)===0x06054b50){eocd=i;break}}
  if(eocd<0)throw new Error('Excel ZIP yapısı bulunamadı');
  const total=readU16(dv,eocd+10), cdOff=readU32(dv,eocd+16), out={}; let p=cdOff;
  for(let n=0;n<total;n++){
    if(readU32(dv,p)!==0x02014b50)break;
    const method=readU16(dv,p+10), csize=readU32(dv,p+20), nlen=readU16(dv,p+28), xlen=readU16(dv,p+30), clen=readU16(dv,p+32), lhoff=readU32(dv,p+42);
    const name=dec.decode(bytes.slice(p+46,p+46+nlen));
    const lnlen=readU16(dv,lhoff+26), lxlen=readU16(dv,lhoff+28), start=lhoff+30+lnlen+lxlen;
    const chunk=bytes.slice(start,start+csize);
    if(method===0)out[name]=chunk; else if(method===8)out[name]=await inflateZipEntry(chunk); else out[name]=null;
    p+=46+nlen+xlen+clen;
  }
  return out;
}
async function inflateZipEntry(chunk){
  if(!('DecompressionStream' in window))throw new Error('XLSX sıkıştırma desteği yok');
  const ds=new DecompressionStream('deflate-raw');
  const stream=new Blob([chunk]).stream().pipeThrough(ds);
  return new Uint8Array(await new Response(stream).arrayBuffer());
}
function xmlDoc(bytes){return new DOMParser().parseFromString(new TextDecoder('utf-8').decode(bytes),'application/xml')}
function cellIndex(ref){let s=String(ref||'').match(/[A-Z]+/i); if(!s)return 0; let n=0; for(const ch of s[0].toUpperCase())n=n*26+(ch.charCodeAt(0)-64); return Math.max(0,n-1)}
function textContentOf(el,tag){const x=el.getElementsByTagName(tag); return x&&x[0]?x[0].textContent:''}
async function xlsxFirstSheetRows(buffer){
  const entries=await unzipXlsx(buffer);
  const sheetName=Object.keys(entries).filter(n=>/^xl\/worksheets\/sheet\d+\.xml$/i.test(n)).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}))[0];
  if(!sheetName||!entries[sheetName])throw new Error('Excel sayfası bulunamadı');
  let shared=[];
  if(entries['xl/sharedStrings.xml']){
    const sx=xmlDoc(entries['xl/sharedStrings.xml']);
    shared=Array.from(sx.getElementsByTagName('si')).map(si=>Array.from(si.getElementsByTagName('t')).map(t=>t.textContent||'').join(''));
  }
  const doc=xmlDoc(entries[sheetName]);
  return Array.from(doc.getElementsByTagName('row')).map(r=>{
    const arr=[]; Array.from(r.getElementsByTagName('c')).forEach(c=>{
      const idx=cellIndex(c.getAttribute('r')), type=c.getAttribute('t'); let val='';
      if(type==='s'){val=shared[Number(textContentOf(c,'v'))]||''}
      else if(type==='inlineStr'){val=Array.from(c.getElementsByTagName('t')).map(t=>t.textContent||'').join('')}
      else val=textContentOf(c,'v')||'';
      arr[idx]=val;
    });
    return arr.map(x=>String(x??'').trim());
  });
}
function showTemplate(){openModal('Şablon örnekleri',`<div class="goldNote">Her satır şu sırada olmalıdır:</div><pre class="note">Hollandaca;Okunuş;İngilizce;Türkçe
recht;reht;law;hukuk
aanvraag;anfrage;application;başvuru</pre><div class="goldNote">CSV, TXT veya doğrudan metin yapıştırma kullanılabilir.</div>`)}
function showAbout(){openModal('Uygulama hakkında',`<div class="aboutText"><p><b>LexLingo</b>, hukuk dili ve genel dil öğrenimini aynı ekranda birleştiren çok modüllü bir çalışma uygulamasıdır. Uygulama Hollandaca, İngilizce ve Türkçe içerikler üzerinde kelime, cümle, paragraf, okuma ve quiz çalışmaları yapmanız için tasarlanmıştır.</p>
<p><b>Kart modülü</b> seçilen kategorideki kelimeyi, okunuş bilgisini, kökü ve dil yönüne göre çevirileri gösterir. Satırlardaki ses simgeleriyle kelime, çeviri veya örnek cümle dinlenebilir. Buzlu alanlara tek tek dokunarak ilgili satırı gösterebilir veya gizleyebilirsiniz.</p>
<p><b>Yazma modülü</b> kelimenin karşılığını yazma pratiği sağlar. Girilen cevaplar kontrol edilir ve doğru cevaplar puanlama sistemine katkı verebilir.</p>
<p><b>Cümle ve paragraf modülleri</b> gerçek kaynak cümleleri ve kategori metinlerini daha geniş bağlamda çalıştırır. Bu alanlarda metinler ve çeviriler seslendirilebilir, ileri/geri ve rasgele gezinme yapılabilir.</p>
<p><b>Okuma modülü</b> seçili kategorideki metinleri kitap sayfası görünümünde sunar. Sayfalar arasında butonlarla veya sağa-sola kaydırma hareketleriyle geçiş yapılabilir; sayfa metni ve çeviriler dinlenebilir.</p>
<p><b>Liste modülü</b> seçili kategorinin kelimelerini sayfalı biçimde gösterir. Listedeki kelimeler dinlenebilir ve seçilen kelime kart modülünde açılabilir.</p>
<p><b>Quiz modülü</b> seçmeli soru, dinleme testi ve telaffuz ölçme çalışmaları içerir. İpucu sistemi, mümkün olduğunda soran ve cevaplayan dil dışındaki üçüncü dildeki karşılığı gösterir; iki dilli durumda ise cevabı açıkça vermeden harf sayısı veya orta bölüm bilgisiyle yönlendirir.</p>
<p><b>Ayarlar bölümü</b> profil, kategori yönetimi, metin yükleme, şablon örnekleri, hatırlatma kartı ve kullanıcı verileri gibi yönetim araçlarını içerir. Silme ve değiştirme işlemleri onay alınmadan uygulanmaz.</p>
<p>Üst bölümdeki ekran boyutu şeridi, uygulamadaki yazı, simge, kart ve buton boyutlarını yanlara taşırmadan dikey ergonomiye göre ayarlar. Kayan yazı alanı ise uygulama duyuruları için kullanılabilir.</p></div>`)}
function openTickerManager(){openModal('Kayan yazı yönetimi',`<div class="formGrid"><label>Kayan yazılar<textarea id="tickerInput" placeholder="Her satıra bir duyuru yazın.">${esc(tickerMessages().join('\n'))}</textarea></label><button onclick="saveTickerMessages()">Kayan yazıyı kaydet</button><div class="goldNote">Birden fazla satır yazarsanız duyurular kayan alanda arka arkaya gösterilir.</div></div>`)}
function saveTickerMessages(){const rows=($('tickerInput')?.value||'').split(/\n+/).map(x=>x.trim()).filter(Boolean); if(!rows.length)return gold('Kayan yazı boş olamaz.'); setJSON('tickerMessages',rows); updateTicker(); closeModal(); gold('Kayan yazı güncellendi.')}
function resetUserData(){['email','customWords','customSources','customCats','hiddenCats','catAliases','reminders',knownKey()].forEach(k=>localStorage.removeItem(LS+k)); profile.email=''; closeModal(); applyFilter(); gold('Kullanıcı verileri sıfırlandı.')}
function openModal(title,body){$('modalBox').innerHTML=`<div class="modalHead"><span>${esc(title)}</span><button class="modalClose" onclick="closeModal()">×</button></div>${body}`; $('modalShade').classList.add('open')}
function closeModal(){$('modalShade').classList.remove('open')}
function closeModalShade(e){if(e.target.id==='modalShade')closeModal()}
function openPicker(type){if(type==='cat'){const html=categories().map(c=>`<button class="modalOpt ${settings.cat===c?'active':''}" onclick="settings.cat='${escAttr(c)}';localStorage.setItem(LS+'cat',settings.cat);closeModal();applyFilter()"><span>${esc(c==='ALL'?'Tüm kategoriler':catName(c))}</span><span>${settings.cat===c?'●':'○'}</span></button>`).join(''); openModal('Kategori seçimi',html)} else {const html=DIRS.map(d=>`<button class="modalOpt ${settings.dir===d[0]?'active':''}" onclick="settings.dir='${d[0]}';localStorage.setItem(LS+'dir',settings.dir);closeModal();render()"><span>${d[1]}</span><span>${settings.dir===d[0]?'●':'○'}</span></button>`).join(''); openModal('Dil yönü seçimi',html)}}
function confirmAction(title,msg,cb){$('confirmTitle').textContent=title;$('confirmMsg').textContent=msg;confirmCb=cb;$('confirmBox').style.display='flex'}
function closeConfirm(ok){$('confirmBox').style.display='none'; if(ok&&confirmCb)confirmCb(); confirmCb=null}
function gold(msg){const t=$('toast'); t.textContent=msg; t.style.display='block'; clearTimeout(window.__toast); window.__toast=setTimeout(()=>t.style.display='none',2600)}
function setMode(m){expanded=false; mode=m; page=0; if(m==='quiz')newQuiz(getJSON('quizType','choice')); render(); window.scrollTo({top:0,behavior:'smooth'})}
function goStart(){if(mode==='read')readPage=0; else if(mode==='list')page=0; else idx=0; render()}
function navNext(){if(mode==='read'){buildReadPages();readPage=Math.min(readPages.length-1,readPage+1)} else if(mode==='list'){page++} else idx=(idx+1)%Math.max(1,filtered.length); render()}
function navPrev(){if(mode==='read')readPage=Math.max(0,readPage-1); else if(mode==='list')page=Math.max(0,page-1); else idx=(idx-1+Math.max(1,filtered.length))%Math.max(1,filtered.length); render()}
function randomItem(){if(mode==='read'){buildReadPages();readPage=Math.floor(Math.random()*Math.max(1,readPages.length))} else if(mode==='list'){const arr=selectedWords();page=Math.floor(Math.random()*Math.max(1,Math.ceil(arr.length/30)))} else idx=Math.floor(Math.random()*Math.max(1,filtered.length)); render()}
document.addEventListener('touchstart',e=>{if(e.touches.length===1)lastTouch={x:e.touches[0].clientX,y:e.touches[0].clientY,t:Date.now()}},{passive:true});
document.addEventListener('touchend',e=>{if(!lastTouch)return; const t=e.changedTouches[0], dx=t.clientX-lastTouch.x, dy=t.clientY-lastTouch.y; if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.4){if($('modalShade').classList.contains('open')){closeModal();return} dx>0?navPrev():navNext();} lastTouch=null},{passive:true});
window.addEventListener('resize',updateHeaderHeight);
function showReminderNow(){const r=Object.values(reminders())[0]||current(); if(!r)return; const o=$('reminderOverlay'); o.innerHTML=`<div class="reminderCard"><button class="reminderClose" onclick="hideReminder()">×</button><span class="badge">LexLingo Hatırlatma</span><div class="word">${esc(r.nl||'')}</div><div class="value">${esc(r.tr||r.en||r.read||'')}</div><button class="ghost" onclick="speakSafe('${enc(r.nl||'')}','nl-NL','rem',this)">🔊 Oku</button></div>`; o.style.display='grid'; clearTimeout(window.__rem); window.__rem=setTimeout(hideReminder,15000)}
function hideReminder(){$('reminderOverlay').style.display='none'}
function scheduleReminder(){setInterval(()=>{const vals=Object.values(reminders()); if(vals.length&&document.visibilityState==='visible'&&Math.random()<.08)showReminderNow()},60000)}

/* --- LexLingo Arabic support patch: adds AR as a first-class content language. --- */
DIRS.splice(0,DIRS.length,
  ['NL_TR_EN_AR','NL → TR + EN + AR'],
  ['NL_TR_EN','NL → TR + EN'],['NL_TR','NL → TR'],['NL_EN','NL → EN'],['NL_AR','NL → AR'],
  ['TR_EN','TR → EN'],['TR_AR','TR → AR'],['TR_NL','TR → NL'],
  ['EN_TR','EN → TR'],['EN_AR','EN → AR'],['EN_NL','EN → NL'],
  ['AR_TR','AR → TR'],['AR_EN','AR → EN'],['AR_NL','AR → NL']
);
const LEX_AR_LANGS={
  NL:{label:'Hollandaca',short:'NL',field:'nl',code:'nl-NL',rtl:false},
  EN:{label:'İngilizce',short:'EN',field:'en',code:'en-US',rtl:false},
  TR:{label:'Türkçe',short:'TR',field:'tr',code:'tr-TR',rtl:false},
  AR:{label:'Arapça',short:'AR',field:'ar',code:'ar-SA',rtl:true}
};
function langMeta(k){return LEX_AR_LANGS[String(k||'NL').toUpperCase()]||LEX_AR_LANGS.NL}
function dirCodes(){let p=String(settings.dir||'NL_TR_EN_AR').split('_').map(x=>x.toUpperCase()).filter(x=>LEX_AR_LANGS[x]); return p.length?p:['NL','TR','EN','AR']}
function primaryCode(){return dirCodes()[0]||'NL'}
function targetCodes(){let p=dirCodes().slice(1); return p.length?p:['TR','EN','AR']}
function fieldByLang(x,k){const m=langMeta(k); return String((x&&x[m.field])||'')}
function textForLang(x,k,allowFallback=true){const m=langMeta(k); let v=fieldByLang(x,k); if(v||!allowFallback)return {code:k,label:m.label,lang:m.code,rtl:m.rtl,text:v}; for(const c of ['NL','TR','EN','AR']){v=fieldByLang(x,c); if(v){const mm=langMeta(c); return {code:c,label:mm.label,lang:mm.code,rtl:mm.rtl,text:v}}} return {code:k,label:m.label,lang:m.code,rtl:m.rtl,text:''}}
function primaryText(x){return textForLang(x,primaryCode(),true)}
function bestTranslation(x){for(const c of targetCodes()){const t=textForLang(x,c,false); if(t.text)return t} for(const c of ['AR','TR','EN','NL']){const t=textForLang(x,c,false); if(t.text)return t} return textForLang(x,'TR',false)}
function langLabel(k){return langMeta(k).label}
function audioLang(label,fallback){if(fallback)return fallback; const f=Object.values(LEX_AR_LANGS).find(x=>x.label===label||x.short===label); return f?f.code:'nl-NL'}
function line(label,val,textForAudio,lang,key){const raw=val||'-', t=textForAudio||raw; const rtl=(lang||'').toLowerCase().startsWith('ar')?' dir="rtl" class="value arabicText"':' class="value" dir="auto"'; return `<div class="line" onclick="toggleLineValue(this)" title="Göster/Gizle"><div>${sp(t,lang,key)}</div><div class="label">${esc(label)}</div><div${rtl}>${esc(raw)}</div></div>`}
function translationRows(x){return targetCodes().map(c=>{const m=langMeta(c), v=fieldByLang(x,c); return [m.label,v,v,m.code,c]}).filter(r=>r[1]||targetCodes().includes('AR'))}
function selectedWords(){let arr=allWords(); if(settings.cat!=='ALL')arr=arr.filter(w=>w.cat===settings.cat); const qv=norm($('q')?.value||''); if(qv)arr=arr.filter(w=>norm([w.nl,w.read,w.root,w.en,w.tr,w.ar,w.cat].join(' ')).includes(qv)); return arr}
function selectedSources(){let arr=allSources(); if(settings.cat!=='ALL')arr=arr.filter(s=>sourceCat(s)===settings.cat); const qv=norm($('q')?.value||''); if(qv)arr=arr.filter(s=>norm([s.nl,s.read,s.en,s.tr,s.ar,s.ref,s.src,sourceCat(s)].join(' ')).includes(qv)); return arr}
function updateHeaderMetrics(){const words=selectedWords(), src=selectedSources(), cats=categories().filter(c=>c!=='ALL'); $('totalWords').textContent=words.length; $('catCount').textContent=cats.length; $('sourceCount').textContent=src.length; const known=knownSet(); $('scoreNum').textContent=known.size; $('progText').textContent=known.size+'/'+Math.max(1,words.length); $('progFill').style.width=Math.min(100,known.size/Math.max(1,words.length)*100)+'%'; $('profileName').textContent=profile.email?profile.email.split('@')[0]:'giriş/kayıt'; $('catBtn').textContent=settings.cat==='ALL'?'Tüm kategoriler':catName(settings.cat); $('dirBtn').textContent=(DIRS.find(d=>d[0]===settings.dir)||DIRS[0])[1];}
function sourcePool(w){let arr=selectedSources(); const p=primaryText(w); if(w&&w.sourceId){let exact=arr.filter(s=>s.id===w.sourceId||s.ref===w.sourceId||s.src===w.sourceId); if(exact.length)return exact} if(w&&p.text){const n=norm(p.text); let exact=arr.filter(s=>norm([s.nl,s.tr,s.en,s.ar].join(' ')).includes(n)); if(exact.length)return exact} return arr}
function sampleSource(w){const arr=sourcePool(w); return arr[(idx+page)%Math.max(1,arr.length)]||{nl:'Bu kelime için kaynak cümle bulunamadı.',en:'',tr:'',ar:'',read:'',cat:w?.cat||settings.cat}}
function renderLearn(){const x=current(); if(!x){$('view').innerHTML='<div class="card">Veri yok.</div>';return} const p=primaryText(x), s=sampleSource(x), known=isKnown(x.id), rem=!!reminders()[x.id]; let html=`<section class="${modClass()}">${tools()}<span class="badge">${esc(catName(x.cat))} • ${idx+1}/${filtered.length||1}</span><div class="word ${p.rtl?'arabicText':''}" dir="${p.rtl?'rtl':'auto'}">${esc(p.text||'-')}</div>${line('Okunuş',x.read||p.text,p.text,p.lang,'read'+x.id)}${line('Kök',x.root||'-',p.text,p.lang,'root'+x.id)}`; translationRows(x).forEach(r=>html+=line(r[0],r[1]||'—',r[2],r[3],r[4]+x.id)); html+=`<div class="row3"><button class="ghost" onclick="toggleAllRows()">Göster/Gizle</button><button class="${known?'ok known':'ok'}" onclick="markKnown()" onpointerdown="holdKnownStart()" onpointerup="holdKnownEnd()" onpointerleave="holdKnownEnd()">${known?'Biliyorum':'Bildim'}</button><button class="ghost ${rem?'goldActive':''}" onclick="toggleReminder()">Hatırlat</button></div>${moduleNav()}</section>`; const ps=primaryText(s), bt=bestTranslation(s); html+=`<section class="card example"><span class="badge">Örnek cümle • ${esc(s.ref||s.src||sourceCat(s)||'Kaynak')}</span><div class="value ${ps.rtl?'arabicText':''}" dir="${ps.rtl?'rtl':'auto'}">${esc(ps.text||'-')}</div><div class="row2"><button class="ghost" onclick="speakSafe('${enc(ps.text||'')}','${ps.lang}','exsrc',this)">🔊 Cümleyi oku</button><button class="ghost" onclick="speakSafe('${enc(bt.text||'')}','${bt.lang}','extr',this)">🔊 Çeviriyi oku</button></div>`; translationRows(s).forEach(r=>{if(r[1])html+=line(r[0],r[1],r[2],r[3],'ex'+r[4])}); html+='</section>'; $('view').innerHTML=html}
function renderWrite(){const x=current(); if(!x)return; const p=primaryText(x), targets=targetCodes(); let inputs=targets.map(c=>`<input id="ans${c}" placeholder="${escAttr(langLabel(c))}">`).join(''); $('view').innerHTML=`<section class="${modClass()}">${tools()}<span class="badge">Yazma • ${(DIRS.find(d=>d[0]===settings.dir)||DIRS[0])[1]}</span><div class="word ${p.rtl?'arabicText':''}" dir="${p.rtl?'rtl':'auto'}">${esc(p.text||'-')}</div><div class="row2"><button class="ghost" onclick="speakSafe('${enc(p.text)}','${p.lang}','writeword',this)">🔊 Kelime</button><button class="ghost" onclick="speakSafe('${enc(bestTranslation(x).text)}','${bestTranslation(x).lang}','writeanswer',this)">🔊 Cevap</button></div><div class="hint">Seçili dil yönüne göre karşılığı yazın. Arapça alanı boşsa Ayarlar bölümünden 5 sütunlu veri yükleyebilirsiniz.</div>${inputs}<button onclick="checkWrite()">Kontrol et</button><div id="writeResult" class="note"></div>${moduleNav()}</section>`}
function checkWrite(){const x=current(); let ok=false, out=[]; targetCodes().forEach(c=>{const m=langMeta(c), expected=fieldByLang(x,c), el=$('ans'+c), got=el?el.value:''; if(!expected){out.push(m.label+': ⚠️ veri yok');return} const good=norm(got)===norm(expected); if(good)ok=true; out.push(m.label+': '+(good?'✅ Doğru':'❌ '+esc(expected)))}); $('writeResult').innerHTML=out.join('<br>'); if(ok)markQuizScore()}
function renderSentences(){const w=current(), arr=sourcePool(w), s=arr[(idx+page)%Math.max(1,arr.length)]||sampleSource(w), p=primaryText(s), bt=bestTranslation(s); let html=`<section class="${modClass()}">${tools()}<span class="badge">Gerçek cümle</span><div class="value ${p.rtl?'arabicText':''}" dir="${p.rtl?'rtl':'auto'}">${esc(p.text||'-')}</div><div class="row2"><button class="ghost" onclick="speakSafe('${enc(p.text)}','${p.lang}','sentp',this)">🔊 Cümle</button><button class="ghost" onclick="speakSafe('${enc(bt.text)}','${bt.lang}','senttr',this)">🔊 Çeviri</button></div><div class="source">Kaynak: ${esc(s.ref||s.src||sourceCat(s)||'-')}</div>`; if(s.read)html+=line('Okunuş',s.read,p.text,p.lang,'sentread'); translationRows(s).forEach(r=>{if(r[1]||r[4]==='AR')html+=line(r[0],r[1]||'—',r[2],r[3],'sent'+r[4])}); html+=`<button onclick="page++;render()">Başka cümle</button>${moduleNav()}</section>`; $('view').innerHTML=html}
function renderParagraph(){const w=current(), arr=sourcePool(w); let start=(idx*3+page*3)%Math.max(1,arr.length); let part=arr.slice(start,start+3); if(!part.length)part=[sampleSource(w)]; const joinCode=c=>part.map(s=>fieldByLang(s,c)).filter(Boolean).join(' '); const pc=primaryCode(), p={text:joinCode(pc)||part.map(s=>s.nl).filter(Boolean).join(' '),lang:langMeta(pc).code,rtl:langMeta(pc).rtl}; let html=`<section class="${modClass()}">${tools()}<span class="badge">Paragraf</span><div class="value ${p.rtl?'arabicText':''}" dir="${p.rtl?'rtl':'auto'}">${esc(p.text||'-')}</div><div class="row2"><button class="ghost" onclick="speakSafe('${enc(p.text)}','${p.lang}','parp',this)">🔊 Paragraf</button><button class="ghost" onclick="speakSafe('${enc(bestTranslation(Object.assign({},...part)).text)}','${bestTranslation(Object.assign({},...part)).lang}','partr',this)">🔊 Çeviri</button></div><div class="source">Kaynak: ${esc(part.map(s=>s.ref||s.src||sourceCat(s)).filter(Boolean).join(' / ')||'-')}</div>`; targetCodes().forEach(c=>{const txt=joinCode(c); if(txt||c==='AR')html+=line(langLabel(c),txt||'—',txt,langMeta(c).code,'par'+c)}); html+=`<button onclick="page++;render()">Başka paragraf</button>${moduleNav()}</section>`; $('view').innerHTML=html}
function buildReadPages(){const src=selectedSources(); const chunks=[]; let buf=[], chars=0; src.forEach(s=>{const p={nl:s.nl||'',en:s.en||'',tr:s.tr||'',ar:s.ar||'',ref:s.ref||s.src||sourceCat(s)}; const add=(p.nl+' '+p.en+' '+p.tr+' '+p.ar).length; if(buf.length&&chars+add>1150){chunks.push(buf);buf=[];chars=0} buf.push(p);chars+=add}); if(buf.length)chunks.push(buf); readPages=chunks.length?chunks:[[]]; if(readPage>=readPages.length)readPage=0}
function renderRead(){buildReadPages(); const items=readPages[readPage]||[], pc=primaryCode(); const join=c=>items.map(x=>fieldByLang(x,c)).filter(Boolean).join(' '); const main=join(pc)||join('NL'); let body=items.map(x=>{const px=textForLang(x,pc,true); let p=`<p><span class="${px.rtl?'arabicText':''}" dir="${px.rtl?'rtl':'auto'}">${esc(px.text)}</span>`; targetCodes().forEach(c=>{const tx=fieldByLang(x,c); if(tx)p+=`<br><span class="${c==='AR'?'goldNote arabicText':'goldNote'}" dir="${c==='AR'?'rtl':'auto'}">${esc(tx)}</span>`}); return p+'</p>'}).join('')||'<p>Bu kategori için okunacak metin bulunamadı.</p>'; const bt=bestTranslation(items.find(x=>bestTranslation(x).text)||{}); $('view').innerHTML=`<section class="${modClass()}">${tools()}<span class="badge">Okuma • ${readPage+1}/${readPages.length}</span><div class="book"><div class="bookTitle">${esc(settings.cat==='ALL'?'Tüm Kategoriler':catName(settings.cat))}</div><div class="bookPage">${body}</div></div><div class="row2"><button class="ghost" onclick="speakSafe('${enc(main)}','${langMeta(pc).code}','readp',this)">🔊 Sayfayı oku</button><button class="ghost" onclick="speakSafe('${enc(bt.text)}','${bt.lang}','readtr',this)">🔊 Çeviri</button></div><div class="moduleNav"><button class="ghost" onclick="readPage=0;render()">⏮ Başa</button><button class="ghost" onclick="readPage=Math.max(0,readPage-1);render()">‹ Geri</button><button class="ghost" onclick="readPage=Math.min(readPages.length-1,readPage+1);render()">İleri ›</button><button class="ghost" onclick="readPage=Math.floor(Math.random()*readPages.length);render()">🔀 Rasgele</button></div></section>`}
function renderList(){const arr=selectedWords(), size=30, pages=Math.max(1,Math.ceil(arr.length/size)); if(page>=pages)page=0; const part=arr.slice(page*size,page*size+size); let html=`<section class="${modClass()}">${tools()}<span class="badge">Liste • ${esc(settings.cat==='ALL'?'Tüm kategoriler':catName(settings.cat))}</span><div class="listPage"><span>${page+1}/${pages} • ${arr.length} kelime</span><span>30'arlı sayfa</span></div><div class="listBox">`; part.forEach((w,i)=>{const p=primaryText(w); html+=`<div class="listItem"><div>${sp(p.text,p.lang,'list'+w.id)}</div><div onclick="idx=${page*size+i};mode='learn';render()"><b class="${p.rtl?'arabicText':''}" dir="${p.rtl?'rtl':'auto'}">${esc(p.text||'-')}</b><small>${esc(w.read||'')} • ${esc(w.en||'')} • ${esc(w.tr||'')} ${w.ar?'• '+esc(w.ar):''}</small></div><button class="ghost iconBtn" onclick="idx=${page*size+i};setMode('learn')">›</button></div>`}); html+=`</div><div class="moduleNav"><button class="ghost" onclick="page=0;render()">⏮ Başa</button><button class="ghost" onclick="page=Math.max(0,page-1);render()">‹ Geri</button><button class="ghost" onclick="page=Math.min(${pages-1},page+1);render()">İleri ›</button><button class="ghost" onclick="page=Math.floor(Math.random()*${pages});render()">🔀 Rasgele</button></div></section>`; $('view').innerHTML=html}
function newQuiz(type){const arr=selectedWords(); const x=arr[Math.floor(Math.random()*Math.max(1,arr.length))]||allWords()[0]; type=type||getJSON('quizType','choice'); const codes=dirCodes(), pc=codes[0]||'NL'; let ac=codes[1]||'TR'; if(!fieldByLang(x,ac)){ac=['AR','TR','EN','NL'].find(c=>c!==pc&&fieldByLang(x,c))||ac} const pp=textForLang(x,pc,true); let answer=fieldByLang(x,ac)||fieldByLang(x,'TR')||fieldByLang(x,'EN')||fieldByLang(x,'NL')||fieldByLang(x,'AR'); const opts=[answer,...arr.filter(y=>y.id!==x.id).sort(()=>Math.random()-.5).slice(0,8).map(y=>fieldByLang(y,ac)).filter(Boolean).slice(0,3)].filter(Boolean).sort(()=>Math.random()-.5); quiz={type,x,prompt:pp.text,answer,opts,sel:null,checked:false,lang:pp.lang,promptCode:pp.code,answerCode:ac}; setJSON('quizType',type)}
function quizLangs(){const p=dirCodes();return {prompt:p[0]||'NL',answer:p[1]||'TR'}}
function smartHint(){if(!quiz||!quiz.x)return 'İpucu hazırlanamadı.'; const la=quizLangs(), all=['NL','EN','TR','AR']; const third=all.find(k=>k!==la.prompt&&k!==la.answer&&fieldByLang(quiz.x,k)); if(third)return 'Üçüncü dil ipucu ('+langLabel(third)+'): '+fieldByLang(quiz.x,third); const ans=String(quiz.answer||'').trim(); if(!ans)return 'Cevap verisi bulunamadı.'; const letters=ans.replace(/\s+/g,''); if(letters.length<=4)return 'Cevap kısa. Harf sayısı: '+letters.length+'. Ses ve bağlama dikkat edin.'; const mid=Math.floor(letters.length/2), frag=letters.slice(Math.max(0,mid-1),Math.min(letters.length,mid+2)); return 'Harf sayısı: '+letters.length+'. Orta bölümden '+frag.length+' harf: '+frag+'.'}
function renderQuiz(){if(!quiz)newQuiz('choice'); let qrtl=(quiz.lang||'').toLowerCase().startsWith('ar'); let html=`<section class="${modClass()}">${tools()}<span class="badge">Quiz</span><div class="row3"><button class="ghost" onclick="newQuiz('choice');render()">Seçmeli</button><button class="ghost" onclick="newQuiz('listen');render()">Dinleme</button><button class="ghost" onclick="newQuiz('pronounce');render()">Telaffuz</button></div>`; if(quiz.type==='listen')html+=`<div class="word">🔊 Dinle ve seç</div><button class="ghost" onclick="speakSafe('${enc(quiz.prompt)}','${quiz.lang}','qlisten',this)">Telaffuzu oku</button>`; else html+=`<div class="word ${qrtl?'arabicText':''}" dir="${qrtl?'rtl':'auto'}">${esc(quiz.prompt||'-')}</div><button class="ghost" onclick="speakSafe('${enc(quiz.prompt||'')}','${quiz.lang}','qprompt',this)">🔊 Oku</button>`; if(quiz.type==='pronounce'){html+=`<div class="hint">Kelimeyi okuyun. Sistem duyduğu metni yaklaşık olarak karşılaştırır.</div><button onclick="startRecognitionSafe('${enc(quiz.prompt||'')}','${quiz.lang}')">🎙 Telaffuzumu ölç</button><div id="speechResult" class="note"></div>`} else {html+='<div class="opts">'+quiz.opts.map(o=>`<button class="opt ${quiz.checked?(norm(o)===norm(quiz.answer)?'good':(o===quiz.sel?'wrong':'')):''}" onclick="quizPickSafe('${enc(o)}')">${esc(o)}</button>`).join('')+'</div>'; if(quiz.checked)html+=`<div class="note ${norm(quiz.sel)===norm(quiz.answer)?'goodText':'badText'}">${norm(quiz.sel)===norm(quiz.answer)?'✅ Doğru':'❌ Yanlış. Doğru: '+esc(quiz.answer)}</div>`} const am=langMeta(quiz.answerCode||'TR'); html+=`<div class="row3"><button onclick="newQuiz(quiz.type);render()">Yeni soru</button><button class="ghost" onclick="gold(smartHint())">İpucu</button><button class="ghost" onclick="speakSafe('${enc(quiz.answer)}','${am.code}','qans',this)">Doğruyu oku</button></div>${moduleNav()}</section>`; $('view').innerHTML=html}
function openTextManager(){const list=categories().filter(c=>c!=='ALL').map(c=>`<option value="${escAttr(c)}">${esc(catName(c))}</option>`).join(''); openModal('Metin yükleme / çıkarma',`<div class="formGrid"><label>Kategori<select id="textCat">${list}</select></label><textarea id="bulkText" placeholder="Her satır: Hollandaca;Okunuş;İngilizce;Türkçe;Arapça"></textarea><button onclick="importTextRows()">Metni kategoriye ekle</button><button class="danger" onclick="clearCategoryCustomText()">Bu kategorideki özel metni çıkar</button></div>`)}
function importTextRows(){const c=$('textCat').value, rows=$('bulkText').value.split(/\n+/).map(x=>x.trim()).filter(Boolean); if(!rows.length)return gold('Metin boş.'); confirmAction('Metin eklensin mi?',rows.length+' satır '+catName(c)+' kategorisine eklenecek.',()=>{const words=customWords(),src=customSources(); rows.forEach((r,i)=>{const p=r.split(/[;\t,]/).map(x=>x.trim()); const nl=p[0]||''; if(!nl)return; const read=p[1]||'', en=p[2]||'', tr=p[3]||'', ar=p[4]||''; const id='CUS-'+Date.now()+'-'+i; words.push({id,cat:c,nl,read,en,tr,ar,root:''}); src.push({id:id+'S',cat:c,source:c,ref:'Kullanıcı',nl,read,en,tr,ar})}); setJSON('customWords',words); setJSON('customSources',src); closeModal(); applyFilter(); gold('Metin eklendi.')})}
function showTemplate(){openModal('Şablon örnekleri',`<div class="goldNote">Her satır şu sırada olmalıdır:</div><pre class="note">Hollandaca;Okunuş;İngilizce;Türkçe;Arapça
recht;reht;law;hukuk;قانون
aanvraag;anfrage;application;başvuru;طلب</pre><div class="goldNote">CSV, TXT veya doğrudan metin yapıştırma kullanılabilir. Beşinci sütun Arapça karşılığıdır.</div>`)}
function showAbout(){openModal('Uygulama hakkında',`<div class="aboutText"><p><b>LexLingo</b>, hukuk dili ve genel dil öğrenimini aynı ekranda birleştiren çok modüllü bir çalışma uygulamasıdır. Bu sürüm Hollandaca, İngilizce, Türkçe ve Arapça alanlarını destekler.</p><p><b>Arapça desteği</b> dil yönü seçiminde AR hedef/kaynak seçeneklerini, sağdan sola metin görünümünü, Arapça seslendirme dil kodunu ve metin yüklemede 5. Arapça sütununu içerir. Mevcut dahili veri paketlerinde Arapça çeviri olmayan satırlarda Arapça alan boş görünebilir.</p><p><b>Kart, Yazma, Cümle, Paragraf, Okuma, Liste ve Quiz modülleri</b> seçili dil yönüne göre çalışır. Satırlardaki ses simgeleriyle metinler dinlenebilir, buzlu alanlara dokunarak göster/gizle yapılabilir.</p><p><b>Ayarlar bölümü</b> profil, kategori yönetimi, metin yükleme, şablon örnekleri, hatırlatma kartı ve kullanıcı verileri gibi yönetim araçlarını içerir. Silme ve değiştirme işlemleri onay alınmadan uygulanmaz.</p></div>`)}
function showReminderNow(){const r=Object.values(reminders())[0]||current(); if(!r)return; const p=primaryText(r), bt=bestTranslation(r); const o=$('reminderOverlay'); o.innerHTML=`<div class="reminderCard"><button class="reminderClose" onclick="hideReminder()">×</button><span class="badge">LexLingo Hatırlatma</span><div class="word ${p.rtl?'arabicText':''}" dir="${p.rtl?'rtl':'auto'}">${esc(p.text||'')}</div><div class="value ${bt.rtl?'arabicText':''}" dir="${bt.rtl?'rtl':'auto'}">${esc(bt.text||'')}</div><button class="ghost" onclick="speakSafe('${enc(p.text||'')}','${p.lang}','rem',this)">🔊 Oku</button></div>`; o.style.display='grid'; clearTimeout(window.__rem); window.__rem=setTimeout(hideReminder,15000)}



