DIRS.splice(0,DIRS.length,
  ['NL_TR_EN_AR_RU','NL → TR + EN + AR + RU'],
  ['NL_TR_EN_AR','NL → TR + EN + AR'],['NL_TR_EN','NL → TR + EN'],
  ['NL_TR','NL → TR'],['NL_EN','NL → EN'],['NL_AR','NL → AR'],['NL_RU','NL → RU'],
  ['TR_NL','TR → NL'],['TR_EN','TR → EN'],['TR_AR','TR → AR'],['TR_RU','TR → RU'],
  ['EN_NL','EN → NL'],['EN_TR','EN → TR'],['EN_AR','EN → AR'],['EN_RU','EN → RU'],
  ['AR_NL','AR → NL'],['AR_TR','AR → TR'],['AR_EN','AR → EN'],['AR_RU','AR → RU'],
  ['RU_NL','RU → NL'],['RU_TR','RU → TR'],['RU_EN','RU → EN'],['RU_AR','RU → AR']
);
const LEX_LANGS={
  NL:{label:'Hollandaca',short:'NL',field:'nl',readField:'read',code:'nl-NL',rtl:false,phonetic:false},
  EN:{label:'İngilizce',short:'EN',field:'en',readField:'en_read',code:'en-US',rtl:false,phonetic:false},
  TR:{label:'Türkçe',short:'TR',field:'tr',readField:'tr_read',code:'tr-TR',rtl:false,phonetic:false},
  AR:{label:'Arapça',short:'AR',field:'ar',readField:'ar_read',code:'ar-SA',rtl:true,phonetic:true},
  RU:{label:'Rusça',short:'RU',field:'ru',readField:'ru_read',code:'ru-RU',rtl:false,phonetic:true}
};
if(!DIRS.find(d=>d[0]===settings.dir))settings.dir='NL_TR_EN_AR_RU';
function langMeta(k){return LEX_LANGS[String(k||'NL').toUpperCase()]||LEX_LANGS.NL}
function dirCodes(){let p=String(settings.dir||'NL_TR_EN_AR_RU').split('_').map(x=>x.toUpperCase()).filter(x=>LEX_LANGS[x]); return p.length?p:['NL','TR','EN','AR','RU']}
function primaryCode(){return dirCodes()[0]||'NL'}
function targetCodes(){let p=dirCodes().slice(1); return p.length?p:['TR','EN','AR','RU']}
function fieldByLang(x,k){const m=langMeta(k); return String((x&&x[m.field])||'')}
function readByLang(x,k){const m=langMeta(k); return String((x&&x[m.readField])||'')}
function voiceByLang(x,k){const v=readByLang(x,k); return v||fieldByLang(x,k)||''}
function textForLang(x,k,allowFallback=true){const m=langMeta(k); let v=fieldByLang(x,k); if(v||!allowFallback)return {code:k,label:m.label,lang:m.code,rtl:m.rtl,text:v,voice:voiceByLang(x,k),read:readByLang(x,k)}; for(const c of ['NL','TR','EN','AR','RU']){v=fieldByLang(x,c); if(v){const mm=langMeta(c); return {code:c,label:mm.label,lang:mm.code,rtl:mm.rtl,text:v,voice:voiceByLang(x,c),read:readByLang(x,c)}}} return {code:k,label:m.label,lang:m.code,rtl:m.rtl,text:'',voice:'',read:''}}
function primaryText(x){return textForLang(x,primaryCode(),true)}
