function langLabel(k){return langMeta(k).label}
function audioLang(label,fallback){if(fallback)return fallback; const f=Object.values(LEX_LANGS).find(x=>x.label===label||x.short===label); return f?f.code:'nl-NL'}
function valueClassForLang(lang){return (lang||'').toLowerCase().startsWith('ar')?' dir="rtl" class="value arabicText"':' class="value" dir="auto"'}
function line(label,val,textForAudio,lang,key){const raw=val||'-', t=textForAudio||raw; return `<div class="line" onclick="toggleLineValue(this)" title="Göster/Gizle"><div>${sp(t,lang,key)}</div><div class="label">${esc(label)}</div><div${valueClassForLang(lang)}>${esc(raw)}</div></div>`}
function pronunciationLine(x,c,key){const m=langMeta(c), r=readByLang(x,c); if(!m.phonetic||!r)return ''; return `<div class="line" onclick="toggleLineValue(this)" title="Göster/Gizle"><div>${sp(r,m.code,key)}</div><div class="label">${esc(m.label+' Okunuş')}</div><div class="value" dir="auto">${esc(r)}</div></div>`}
function translationRows(x){return targetCodes().map(c=>{const m=langMeta(c), v=fieldByLang(x,c); return [m.label,v,voiceByLang(x,c),m.code,c]}).filter(r=>r[1]||['AR','RU'].includes(r[4]))}
function selectedWords(){let arr=allWords(); if(settings.cat!=='ALL')arr=arr.filter(w=>w.cat===settings.cat); const qv=norm($('q')?.value||''); if(qv)arr=arr.filter(w=>norm([w.nl,w.read,w.root,w.en,w.tr,w.ar,w.ar_read,w.ru,w.ru_read,w.cat].join(' ')).includes(qv)); return arr}
