function renderLearn(){const x=current(); if(!x){$('view').innerHTML='<div class="card">Veri yok.</div>';return} const pc=primaryCode(), p=primaryText(x), s=sampleSource(x), known=isKnown(x.id), rem=!!reminders()[x.id]; let html=`<section class="${modClass()}">${tools()}<span class="badge">${esc(catName(x.cat))} • ${idx+1}/${filtered.length||1}</span><div class="word ${p.rtl?'arabicText':''}" dir="${p.rtl?'rtl':'auto'}">${esc(p.text||'-')}</div>`; html+=line('Okunuş',readByLang(x,pc)||x.read||p.text,p.voice||p.text,p.lang,'read'+x.id); html+=line('Kök',x.root||'-',p.voice||p.text,p.lang,'root'+x.id); translationRows(x).forEach(r=>{html+=line(r[0],r[1]||'—',r[2]||r[1],r[3],r[4]+x.id); html+=pronunciationLine(x,r[4],'pron'+r[4]+x.id)}); html+=`<div class="row3"><button class="ghost" onclick="toggleAllRows()">Göster/Gizle</button><button class="${known?'ok known':'ok'}" onclick="markKnown()" onpointerdown="holdKnownStart()" onpointerup="holdKnownEnd()" onpointerleave="holdKnownEnd()">${known?'Biliyorum':'Bildim'}</button><button class="ghost ${rem?'goldActive':''}" onclick="toggleReminder()">Hatırlat</button></div>${moduleNav()}</section>`; const ps=primaryText(s), bt=bestTranslation(s); html+=`<section class="card example"><span class="badge">Örnek cümle • ${esc(s.ref||s.src||sourceCat(s)||'Kaynak')}</span><div class="value ${ps.rtl?'arabicText':''}" dir="${ps.rtl?'rtl':'auto'}">${esc(ps.text||'-')}</div><div class="row2"><button class="ghost" onclick="speakSafe('${enc(ps.voice||ps.text||'')}','${ps.lang}','exsrc',this)">🔊 Cümleyi oku</button><button class="ghost" onclick="speakSafe('${enc(bt.voice||bt.text||'')}','${bt.lang}','extr',this)">🔊 Çeviriyi oku</button></div>`; translationRows(s).forEach(r=>{if(r[1]){html+=line(r[0],r[1],r[2]||r[1],r[3],'ex'+r[4]); html+=pronunciationLine(s,r[4],'expron'+r[4])}}); html+='</section>'; $('view').innerHTML=html}
function renderWrite(){const x=current(); if(!x)return; const p=primaryText(x), targets=targetCodes(); let inputs=targets.map(c=>`<input id="ans${c}" placeholder="${escAttr(langLabel(c))}">`).join(''); $('view').innerHTML=`<section class="${modClass()}">${tools()}<span class="badge">Yazma • ${(DIRS.find(d=>d[0]===settings.dir)||DIRS[0])[1]}</span><div class="word ${p.rtl?'arabicText':''}" dir="${p.rtl?'rtl':'auto'}">${esc(p.text||'-')}</div><div class="row2"><button class="ghost" onclick="speakSafe('${enc(p.voice||p.text)}','${p.lang}','writeword',this)">🔊 Kelime</button><button class="ghost" onclick="speakSafe('${enc(bestTranslation(x).voice||bestTranslation(x).text)}','${bestTranslation(x).lang}','writeanswer',this)">🔊 Cevap</button></div><div class="hint">Seçili dil yönüne göre karşılığı yazın. Arapça ve Rusça için ayrıca Türk alfabesiyle okunuş alanı desteklenir.</div>${inputs}<button onclick="checkWrite()">Kontrol et</button><div id="writeResult" class="note"></div>${moduleNav()}</section>`}
