function speakSeqFromEncoded(encoded){var text=decodeURIComponent(encoded||'').split(/\n+/).map(function(x){return x.trim()}).filter(Boolean); if(!text.length)return gold('Çeviri metni yok.'); var i=0; function next(){if(i>=text.length){stopAudio();return} var t=text[i++]; try{if('speechSynthesis' in window&&typeof SpeechSynthesisUtterance!=='undefined'){var u=new SpeechSynthesisUtterance(t); u.lang='nl-NL'; u.rate=.86; u.onend=next; u.onerror=next; speechSynthesis.speak(u)}else{speak(t,'nl-NL','seq',null); setTimeout(next,Math.min(20000,1500+t.length*70))}}catch(e){next()}} stopAudio(); currentAudioKey='seq'; next()}
function renderParagraph(){var w=current(), arr=sourcePool(w); var start=(idx*3+page*3)%Math.max(1,arr.length); var part=arr.slice(start,start+3); if(!part.length)part=[sampleSource(w)]; var pc=primaryCode(); function join(c){return part.map(function(s){return fieldByLang(s,c)}).filter(Boolean).join(' ')} function joinVoice(c){return part.map(function(s){return voiceByLang(s,c)}).filter(Boolean).join(' ')} var m=langMeta(pc), p={text:join(pc)||part.map(function(s){return s.nl}).filter(Boolean).join(' '),voice:joinVoice(pc),lang:speechCode(pc),rtl:m.rtl}; var bt=bestTranslation(Object.assign.apply(Object,[{}].concat(part))); var html=`<section class="${modClass()}">${tools()}<span class="badge">Paragraf</span><div class="value ${p.rtl?'arabicText':''}" dir="${p.rtl?'rtl':'auto'}">${esc(p.text||'-')}</div><div class="row3"><button class="ghost" onclick="speakSafe('${enc(p.voice||p.text)}','${p.lang}','parp',this)">🔊 Paragraf</button><button class="ghost" onclick="speakSafe('${enc(bt.voice||bt.text)}','${bt.lang}','partr',this)">🔊 Çeviri</button><button class="ghost" onclick="shareText('${enc(dirCodes().map(function(c){return join(c)}).filter(Boolean).join('\n'))}')">↗ Paylaş</button></div><div class="source">Kaynak: ${esc(part.map(function(s){return s.ref||s.src||sourceCat(s)}).filter(Boolean).join(' / ')||'-')}</div>`; targetCodes().forEach(function(c){var txt=join(c), voice=joinVoice(c), mm=langMeta(c); if(txt||['AR','RU'].includes(c))html+=line(langLabel(c),txt||'—',voice,speechCode(c),'par'+c,part.map(function(s){return readByLang(s,c)}).filter(Boolean).join(' ')); var read=part.map(function(s){return readByLang(s,c)}).filter(Boolean).join(' '); if(read)html+=`<div class="line" onclick="lexLineToggle(event,this)" title="Göster/Gizle"><div>${sp(read,'tr-TR','parpron'+c)}</div><div class="label">${esc(mm.label+' Okunuş')}</div><div class="value" dir="auto">${esc(read)}</div></div>`}); html+=`<button onclick="page++;render()">Başka paragraf</button>${moduleNav()}</section>`; $('view').innerHTML=html}
function newQuiz(type){var arr=selectedWords(); var x=arr[Math.floor(Math.random()*Math.max(1,arr.length))]||allWords()[0]; type=type||getJSON('quizType','choice'); if(!x){quiz=null;return} var pc=primaryCode(), ac=targetCodes()[0]||'EN'; if(!fieldByLang(x,ac)) ac=targetCodes().find(function(c){return fieldByLang(x,c)})||LEX_LANG_SEQUENCE.find(function(c){return c!==pc&&fieldByLang(x,c)})||'EN'; var pp=textForLang(x,pc,true); var answer=fieldByLang(x,ac)||LEX_LANG_SEQUENCE.map(function(c){return c!==pc?fieldByLang(x,c):''}).find(Boolean)||fieldByLang(x,pc)||''; var opts=[answer].concat(arr.filter(function(y){return y.id!==x.id}).sort(function(){return Math.random()-.5}).slice(0,10).map(function(y){return fieldByLang(y,ac)}).filter(Boolean).slice(0,3)).filter(Boolean).sort(function(){return Math.random()-.5}); quiz={type:type,x:x,prompt:pp.text,voice:pp.voice,answer:answer,answerVoice:voiceByLang(x,ac)||answer,opts:opts,sel:null,checked:false,lang:pp.lang,promptCode:pp.code,answerCode:ac}; setJSON('quizType',type)}
