function patchTopAndBottom(){
 const top=document.querySelector('.topActions'); if(top) top.innerHTML=`<button class="ghost" onclick="goStart()">⏮ Başa</button><button class="ghost" onclick="navPrev()">‹ Geri</button><button class="ghost" onclick="navNext()">İleri ›</button><button class="ghost" onclick="randomItem()">🔀 Rasgele</button><button class="ghost" onclick="setMode('manage')">⚙ Ayar</button>`;
 const tabs=document.querySelector('.tabsInner'); if(tabs) tabs.innerHTML=`<button class="tabBtn" id="tabLearn" onclick="setMode('learn')"><span class="tabIcon">▣</span><span>Kart</span></button><button class="tabBtn" id="tabWrite" onclick="setMode('write')"><span class="tabIcon">✎</span><span>Yazma</span></button><button class="tabBtn" id="tabSentences" onclick="setMode('sentences')"><span class="tabIcon">💬</span><span>Cümle</span></button><button class="tabBtn" id="tabParagraph" onclick="setMode('paragraph')"><span class="tabIcon">▤</span><span>Gramer</span></button><button class="tabBtn" id="tabRead" onclick="setMode('read')"><span class="tabIcon">📖</span><span>Okuma</span></button><button class="tabBtn" id="tabList" onclick="setMode('list')"><span class="tabIcon">☷</span><span>Liste</span></button><button class="tabBtn" id="tabQuiz" onclick="setMode('quiz')"><span class="tabIcon">?</span><span>Quiz</span></button><button class="tabBtn" id="tabAvOfis" onclick="setMode('avofis')"><span class="tabIcon">⚖</span><span>AvOfis</span></button>`;
}
window.moduleNav=function(){return `<div class="moduleNav"><button class="ghost" onclick="goStart()">⏮ Başa</button><button class="ghost" onclick="navPrev()">‹ Önceki</button><button class="ghost" onclick="navNext()">Sonraki ›</button><button class="ghost" onclick="randomItem()">🔀 Rastgele</button><button class="ghost" onclick="v2GoEnd()">⏭ Sona</button></div>`}
window.v2GoEnd=function(){if(v2Mode()==='paragraph'){setGrammarIndex(allLessons().length-1); render(); return} try{const arr=selectedWords(); idx=Math.max(0,arr.length-1); render()}catch(e){}}
const oldSetActive=window.setActiveTab;
window.setActiveTab=function(){document.querySelectorAll('.tabBtn').forEach(b=>b.classList.remove('active')); const map={learn:'tabLearn',write:'tabWrite',sentences:'tabSentences',paragraph:'tabParagraph',read:'tabRead',list:'tabList',quiz:'tabQuiz',avofis:'tabAvOfis',manage:''}; const el=$id(map[v2Mode()]||''); if(el)el.classList.add('active')}
function lessonForSpot(id){return allLessons().find(x=>x.id===id)||allLessons().find(x=>x.spot===id)}
window.v2OpenSpot=function(id){const s=allSpots().find(x=>x.id===id); if(!s)return; openModal(sx(s.title),`<div style="text-align:center"><img class="fullImg" src="${ax(s.image||s.dataUrl||'')}" alt="${ax(s.title)}"><p class="goldNote">${sx(s.level||'')} • ${sx(s.cat||'')}<br>${sx(s.desc||'')}</p><div class="row3"><button onclick="v2JumpLesson('${ax(s.lesson||'')}')">İlgili derse git</button><button class="ghost" onclick="shareText('${en((s.title||'')+'\n'+(s.desc||''))}')">↗ Paylaş</button><button class="ghost" onclick="closeModal()">Kapat</button></div></div>`)}
window.v2JumpLesson=function(id){const i=allLessons().findIndex(x=>x.id===id); if(i>=0){setGrammarIndex(i); localStorage.setItem(V2_LS+'grammarTab','course'); closeModal(); v2SetMode('paragraph')}}
window.v2FavLesson=function(id){const s=favs(); if(s.has(id))s.delete(id); else s.add(id); saveFavs(s); render()}
window.v2SpeakLesson=function(id){const l=allLessons().find(x=>x.id===id); if(!l)return; const text=[l.title,l.rule,l.tr,l.nl,l.translation].filter(Boolean).join('. '); try{speakSafe(en(text),'tr-TR','v2lesson'+id,null)}catch(e){try{speak(text,'tr-TR','v2lesson'+id,null)}catch(_){}}}
window.v2AIPromptLesson=function(id){const l=allLessons().find(x=>x.id===id); const body=l?`Konu: ${l.title}\nSeviye: ${l.level}\nKural: ${l.rule}\nAçıklama: ${l.tr}\nÖrnek: ${l.nl}\nÇeviri: ${l.translation}\nHata: ${l.mistake}\nAlıştırma: ${l.exercise}`:'Buraya metni yazın.'; const p=`Aşağıdaki Hollandaca gramer içeriğini mobil uygulama için daha sade, örnekli, A2/B1 uyumlu ve sınav odaklı hale getir. Kişisel veri varsa maskele. Çıktı: başlık, seviye, kısa açıklama, ana kural, Türkçe anlatım, Hollandaca örnek, Türkçe çeviri, sık hata, mini alıştırma, AI çalışma talimatı.\n\n${body}`; openModal('AI talimatı',`<div class="formGrid"><textarea id="aiPrompt">${sx(p)}</textarea><button onclick="copyText(encodeURIComponent($id('aiPrompt').value))">Promptu kopyala</button><button class="ghost" onclick="openExternal('https://chat.openai.com/')">ChatGPT aç</button><button class="ghost" onclick="openExternal('https://gemini.google.com/')">Gemini aç</button></div>`)}
function renderLessonCard(l,i){const fs=favs(); const s=allSpots().find(x=>x.id===l.spot||x.lesson===l.id); return `<article class="lessonCard"><div class="lessonHead"><h3>${sx(l.title)}</h3><span class="levelTag">${sx(l.level)} • ${sx(l.group)}</span></div><div class="v2Sub" style="text-align:left;color:#334155">${sx(l.short)}</div><div class="pillLine">${(l.tags||[]).map(t=>`<span class="miniPill">${sx(t)}</span>`).join('')}</div><div class="lessonSection"><b>Ana kural</b><div>${sx(l.rule)}</div></div><div class="lessonTr"><b>Türkçe anlatım</b><br>${sx(l.tr)}</div><div class="lessonExample"><b>Hollandaca örnek</b><br>${sx(l.nl)}<br><b>Türkçe</b><br>${sx(l.translation)}</div><div class="lessonDanger"><b>Sık hata</b><br>${sx(l.mistake)}</div><div class="lessonSection"><b>Mini alıştırma</b><br>${sx(l.exercise)}<details><summary>Cevabı göster</summary>${sx(l.answer)}</details></div><div class="lessonActions"><button class="ghost" onclick="v2SpeakLesson('${ax(l.id)}')">🔊 Okut</button><button class="ghost ${fs.has(l.id)?'goldActive':''}" onclick="v2FavLesson('${ax(l.id)}')">★ Favori</button><button class="ghost" onclick="shareText('${en(l.title+'\n'+l.rule+'\n'+l.nl+'\n'+l.translation)}')">↗ Paylaş</button><button class="ghost" onclick="v2AIPromptLesson('${ax(l.id)}')">AI</button>${s?`<button class="ghost" onclick="v2OpenSpot('${ax(s.id)}')">Görsel</button>`:''}</div></article>`}
function renderGrammarCourse(){const q=($id('q')?.value||'').toLocaleLowerCase('tr'); let arr=allLessons().filter(l=>!q||[l.title,l.level,l.group,l.short,l.rule,l.tr,l.nl,l.translation].join(' ').toLocaleLowerCase('tr').includes(q)); const gi=currentGrammarIndex(); const current=allLessons()[gi]||arr[0]; return `<section class="v2Hero routeClean">${tools?tools():''}<div class="v2Title">Gramer Kursu</div><div class="v2Sub">A1 → A2 → B1 sistematik öğrenme yolu. PDF ve görseller belge butonu olarak değil; ders, kart, örnek, pratik ve görsel spot yapısına dönüştürüldü.</div><div class="coursePath"><div class="levelPill"><b>A1</b><span>Temel cümle</span></div><div class="levelPill"><b>A2</b><span>Sınav + günlük dil</span></div><div class="levelPill"><b>B1</b><span>Yazma + bağlaç</span></div></div><div class="v2Tabs"><button class="${getGrammarTab()==='course'?'active':''}" onclick="setGrammarTab('course')">Dersler</button><button class="${getGrammarTab()==='spots'?'active':''}" onclick="setGrammarTab('spots')">Görseller</button><button class="${getGrammarTab()==='practice'?'active':''}" onclick="setGrammarTab('practice')">Pratik</button><button class="${getGrammarTab()==='road'?'active':''}" onclick="setGrammarTab('road')">Yol</button></div>${getGrammarTab()==='course'?`<div class="lessonGrid">${arr.map(renderLessonCard).join('')}</div>`:getGrammarTab()==='spots'?renderSpotGrid():getGrammarTab()==='practice'?renderPractice():renderRoad()}${moduleNav()}</section>`}
function renderSpotGrid(){const imgs=allSpots().concat(mediaImages().filter(x=>x.publishState==='published').map(x=>({id:x.id,title:x.title,level:x.level||'',cat:x.cat||'Kullanıcı',desc:x.desc||'',image:x.dataUrl||x.image,lesson:x.lesson||''}))); return `<div class="spotGrid">${imgs.map(s=>`<article class="spotCard"><img src="${ax(s.image||s.dataUrl||'')}" onclick="v2OpenSpot('${ax(s.id)}')"><div class="spotBody"><b>${sx(s.title)}</b><small>${sx(s.level)} • ${sx(s.cat)}</small><p>${sx(s.desc||'')}</p><div class="spotTools"><button class="ghost" onclick="v2OpenSpot('${ax(s.id)}')">Tam ekran</button><button class="ghost" onclick="v2JumpLesson('${ax(s.lesson||'')}')">Derse git</button><button class="ghost" onclick="shareText('${en((s.title||'')+'\n'+(s.desc||''))}')">Paylaş</button><button class="ghost" onclick="v2FavLesson('${ax(s.lesson||s.id)}')">Favori</button></div></div></article>`).join('')}</div>`}
function renderPractice(){const items=['Bugün ne yapıyorsun? Present tense ile 3 cümle kur.','Dün ne yaptın? Perfectum ile 3 cümle kur.','Eskiden ne yapardın? Imperfectum ile 2 cümle kur.','Bir sebep açıkla: omdat ve want ile iki ayrı cümle kur.','Bir B1 e-postası için kop-romp-staart planı yaz.']; return `<div class="practiceBox"><h3>Mini kurs pratiği</h3>${items.map((x,i)=>`<div class="practiceItem"><b>${i+1}. ${sx(x)}</b><textarea placeholder="Cevabını buraya yaz..."></textarea><button class="ghost" onclick="v2PracticeAI(${i})">AI ile kontrol talimatı</button></div>`).join('')}</div>`}
window.v2PracticeAI=function(i){const p='Aşağıdaki Hollandaca cevabımı A2/B1 seviyesine göre kontrol et. Hataları Türkçe açıkla, doğru versiyon ver, bir de daha doğal alternatif yaz.\n\n'+(document.querySelectorAll('.practiceItem textarea')[i]?.value||''); openModal('AI kontrol talimatı',`<div class="formGrid"><textarea>${sx(p)}</textarea><button onclick="copyText('${en(p)}')">Kopyala</button></div>`)}
function renderRoad(){return `<div class="practiceBox"><h3>Öğrenme yolu</h3><ol><li>A1: kısa tam cümle, present tense, soru, olumsuzluk.</li><li>A2: perfectum, modal fiiller, gelecek, bağlaçlar, günlük konuşma.</li><li>A2 sınav: tam cümle + sebep + günlük hayat örneği.</li><li>B1: yan cümle, inversie, e-posta, şikâyet, görüş bildirme.</li><li>Her ders: oku → sesli dinle → mini alıştırma → spot görsel → AI kontrol.</li></ol><p class="noteSmall">Yeni görsel, ses ve açıklama ekleme işlemleri Ayarlar bölümünden yapılır; öğrenme modülleri yalnızca yayınlanmış içeriği gösterir.</p></div>`}
window.renderGrammarSpot=renderGrammarCourse;
function renderAudioModern(){const built=(window.LEXLINGO_BUILTIN_AUDIO||[]).map(a=>Object.assign({publishState:'published',source:'built-in'},a)); const arr=built.concat(mediaAudio().filter(x=>x.publishState==='published')); if(!arr.length){$id('view').innerHTML=`<section class="card">${tools?tools():''}<span class="badge">Sesli içerik</span><p>Henüz yayınlanmış sesli içerik yok. Ses ve transkript ekleme Ayarlar bölümünden yapılır.</p>${moduleNav()}</section>`; return} if(readPage>=arr.length)readPage=0; const a=arr[readPage]; const lines=parseSegments(a.lyrics||a.segmentsText||''); $id('view').innerHTML=`<section class="audioPro2 routeClean">${tools?tools():''}<span class="badge">Sesli içerik • ${readPage+1}/${arr.length}</span><div class="bookTitle" style="position:relative;border-radius:16px">${sx(a.title||'Sesli parça')}</div><audio id="audioPlayer" class="audioPlayer" controls src="${ax(a.audioUrl||a.dataUrl||'')}"></audio><div class="audioTime"><span id="audCur">00:00</span><span id="audDur">00:00</span></div><div class="audioControls row4"><button class="ghost" onclick="lexAudioSeek(-5)">↶ 5 sn</button><button class="ghost" onclick="lexAudioSeek(5)">5 sn ↷</button><button class="ghost" onclick="lexAudioSpeed()">Hız</button><button class="ghost" onclick="lexRepeatSection()">Tekrar</button></div><div class="segments" id="segBox">${lines.map((l,i)=>`<div class="segment" data-s="${l.s}" data-e="${l.e}" onclick="v2Seg(${i})"><time>${fmt(l.s)}–${fmt(l.e)}</time><div>${sx(l.text)}</div></div>`).join('')||'<div class="segment"><time>00:00</time><div>Transkript eklenmemiş. Ayarlar > Sesli içerik yönetimi bölümünden zamanlı söz ekleyin.</div></div>'}</div><div class="row3"><button class="ghost" onclick="v2DictationView()">Dikte</button><button class="ghost" onclick="shareText('${en((a.title||'')+'\n'+(a.lyrics||''))}')">↗ Paylaş</button><button class="ghost" onclick="setMode('manage')">Ayarlar</button></div><div id="audioPractice" class="noteSmall"></div>${moduleNav()}</section>`; wireAudio2();}
function fmt(s){s=Math.max(0,Number(s)||0); const m=Math.floor(s/60), ss=Math.floor(s%60); return String(m).padStart(2,'0')+':'+String(ss).padStart(2,'0')}
function parseSegments(txt){return String(txt||'').split(/\n+/).map((line,i)=>{line=line.trim(); if(!line)return null; let m=line.match(/^\[(\d{1,2}):(\d{2})(?:[.,](\d+))?\](?:\s*\[(\d{1,2}):(\d{2})(?:[.,](\d+))?\])?\s*(.*)$/); if(m){let s=Number(m[1])*60+Number(m[2])+Number('0.'+(m[3]||0)); let e=m[4]?Number(m[4])*60+Number(m[5])+Number('0.'+(m[6]||0)):s+5; return {s,e,text:m[7]||''}} return {s:i*5,e:(i+1)*5,text:line}}).filter(Boolean)}
function wireAudio2(){const a=$id('audioPlayer'), box=$id('segBox'); if(!a)return; a.ontimeupdate=function(){const t=a.currentTime||0; $id('audCur').textContent=fmt(t); if(a.duration)$id('audDur').textContent=fmt(a.duration); const segs=Array.from(box?.querySelectorAll('.segment')||[]); let active=-1; segs.forEach((el,i)=>{const s=Number(el.dataset.s), e=Number(el.dataset.e); if(t>=s&&t<(e||s+5))active=i}); segs.forEach((el,i)=>el.classList.toggle('active',i===active)); if(active>=0)segs[active].scrollIntoView({block:'nearest',behavior:'smooth'})}}
window.v2Seg=function(i){const a=$id('audioPlayer'), seg=document.querySelectorAll('.segment')[i]; if(a&&seg){a.currentTime=Number(seg.dataset.s)||0; a.play()}}
window.lexAudioSeek=function(s){const a=$id('audioPlayer'); if(a)a.currentTime=Math.max(0,(a.currentTime||0)+s)}
window.lexAudioSpeed=function(){const a=$id('audioPlayer'); if(!a)return; const speeds=[.75,1,1.15,1.3,1.5]; let i=speeds.indexOf(a.playbackRate); a.playbackRate=speeds[(i+1+speeds.length)%speeds.length]; msg('Hız: '+a.playbackRate+'x')}
window.lexRepeatSection=function(){const a=$id('audioPlayer'); if(a){a.currentTime=0; a.play(); msg('Tekrar başladı.')}}
window.v2DictationView=function(){$id('audioPractice').innerHTML='<textarea placeholder="Dinlediğini yaz..."></textarea><button class="ghost" onclick="msg(\'Dikte taslağı kaydedildi.\')">Taslak kaydet</button>'}
function renderManageV2(){ $id('view').innerHTML=`<section class="card routeClean">${tools?tools():''}<span class="badge">Ayarlar • profesyonel içerik yönetimi</span><div class="settingsPanel"><div class="settingsCard"><h3>Medya ve içerik yönetimi</h3><p>Görsel, ses, belge, transkript ve açıklamalar yalnızca buradan eklenir. Öğrenme modülleri yayınlanmış içeriği gösterir.</p><div class="settingsGrid"><button onclick="openImageBulkManager()">Toplu görsel yükle/düzenle</button><button onclick="openAudioBulkManager()">Toplu ses yükle/transkript</button><button class="ghost" onclick="openDocManager()">Belge/not yönetimi</button><button class="ghost" onclick="openGrammarAdmin()">Gramer dersi ekle</button></div></div><div class="settingsCard"><h3>Taslak → Yayın</h3><p>Her içerik önce taslak kaydedilir; kontrol sonrası yayınlanır. Silinen içerikler bağlı ders, spot, ses ve portal alanlarından temizlenir.</p><div class="settingsGrid"><button class="ghost" onclick="openContentLibrary()">İçerik kütüphanesi</button><button class="ghost" onclick="openSpeechToTextTool()">Ses → Yazı aracı</button><button class="ghost" onclick="openTickerManagerV2()">Kayan haber ayarı</button><button class="ghost" onclick="showTemplate()">Şablonlar</button></div></div><div class="settingsCard"><h3>AvOfis / Portal</h3><p>AvOfis portalı uygulama içinde içerik kartları ve canlı portal görünümüyle çalışır; dışa çıkışlarda geri dönüş butonu korunur.</p><div class="settingsGrid"><button onclick="openAvofisManagerV2()">AvOfis içerik yönetimi</button><button class="ghost" onclick="setMode('avofis')">AvOfis modülünü aç</button><button class="ghost" onclick="openInAppPortal('${V2_URL}','AvOfis canlı portal')">Canlı portal</button><button class="ghost" onclick="v2AvofisAIPrompt()">AI belge talimatı</button></div></div><div class="settingsCard"><h3>Güvenlik ve veri temizliği</h3><p>Kişisel veri içeren içerikler AI’ye gönderilmeden önce maskeleme/onay gerektirir. Silme işlemleri bağlı alanlardan da temizlenir.</p><div class="settingsGrid"><button class="ghost" onclick="exportUserData&&exportUserData()">Yedek al</button><button class="ghost" onclick="openCloudManager&&openCloudManager()">Yedek yükle</button><button class="dangerMini" onclick="confirmAction('Kullanıcı verilerini sıfırla','Tüm özel medya, not, skor ve taslak veriler temizlenecek.',resetUserDataV2)">Tüm özel verileri sıfırla</button></div></div></div>${moduleNav()}</section>`}
window.openImageBulkManager=function(){openModal('Toplu görsel yükleme',`<div class="formGrid"><label>Görselleri seç<input id="imgBulk" type="file" accept="image/*" multiple onchange="previewImageBulk()"></label><div id="imgPreview" class="uploadList"></div><button onclick="saveImageBulk()">Taslak olarak kaydet</button><div class="goldNote">Her görsele yükleme sırasında başlık, seviye, kategori ve açıklama yazabilirsiniz. Daha sonra İçerik kütüphanesinden düzenlenebilir.</div></div>`)}
window.previewImageBulk=function(){const files=Array.from($id('imgBulk')?.files||[]); $id('imgPreview').innerHTML=files.map((f,i)=>`<div class="uploadMeta"><b>${sx(f.name)}</b><input id="imgT${i}" placeholder="Başlık" value="${ax(f.name.replace(/\.[^.]+$/,''))}"><input id="imgC${i}" placeholder="Kategori / konu"><input id="imgL${i}" placeholder="Seviye"><textarea id="imgD${i}" placeholder="Açıklama / derse bağlama notu"></textarea></div>`).join('')}
window.saveImageBulk=function(){const files=Array.from($id('imgBulk')?.files||[]); if(!files.length)return msg('Görsel seçilmedi.'); let arr=mediaImages(), left=files.length; files.forEach((f,i)=>{const r=new FileReader(); r.onload=()=>{arr.unshift({id:nowid('img'),title:$id('imgT'+i)?.value||f.name,cat:$id('imgC'+i)?.value||'Kullanıcı görseli',level:$id('imgL'+i)?.value||'',desc:$id('imgD'+i)?.value||'',dataUrl:String(r.result||''),publishState:'draft',t:Date.now()}); if(--left===0){saveMediaImages(arr); closeModal(); msg('Görseller taslak olarak kaydedildi. İçerik kütüphanesinden yayınlayın.')}}; r.readAsDataURL(f)})}
window.openAudioBulkManager=function(){openModal('Toplu ses yükleme ve transkript',`<div class="formGrid"><label>Ses dosyaları<input id="audBulk" type="file" accept="audio/*" multiple onchange="previewAudioBulk()"></label><div id="audPreview" class="uploadList"></div><button onclick="saveAudioBulk()">Taslak olarak kaydet</button><div class="goldNote">Söz/transkript formatı: [00:12] [00:18] metin veya [00:12] metin. Saniye göstergesi dinleme ekranında otomatik çalışır.</div></div>`)}
window.previewAudioBulk=function(){const files=Array.from($id('audBulk')?.files||[]); $id('audPreview').innerHTML=files.map((f,i)=>`<div class="uploadMeta"><b>${sx(f.name)}</b><input id="audT${i}" placeholder="Başlık" value="${ax(f.name.replace(/\.[^.]+$/,''))}"><input id="audC${i}" placeholder="Kategori / konu"><textarea id="audD${i}" placeholder="Açıklama"></textarea><textarea id="audL${i}" placeholder="[00:00] [00:05] söz / açıklama / transkript"></textarea></div>`).join('')}
window.saveAudioBulk=function(){const files=Array.from($id('audBulk')?.files||[]); if(!files.length)return msg('Ses dosyası seçilmedi.'); let arr=mediaAudio(), left=files.length; files.forEach((f,i)=>{const r=new FileReader(); r.onload=()=>{arr.unshift({id:nowid('aud'),title:$id('audT'+i)?.value||f.name,cat:$id('audC'+i)?.value||'Sesli içerik',desc:$id('audD'+i)?.value||'',lyrics:$id('audL'+i)?.value||'',dataUrl:String(r.result||''),publishState:'draft',t:Date.now()}); if(--left===0){saveMediaAudio(arr); closeModal(); msg('Sesler taslak kaydedildi. İçerik kütüphanesinden yayınlayın.')}}; r.readAsDataURL(f)})}
window.openContentLibrary=function(){const imgs=mediaImages(), aud=mediaAudio(), docs=mediaDocs(); const row=(x,type)=>`<div class="mediaRow">${type==='img'?`<img src="${ax(x.dataUrl)}">`:'<div class="profileIcon">'+(type==='aud'?'♪':'□')+'</div>'}<div><b>${sx(x.title)}</b><small>${sx(x.cat||'')} • ${sx(x.publishState||'draft')}<br>${sx(x.desc||'')}</small></div><div><button class="ghost" onclick="togglePublish('${type}','${x.id}')">${x.publishState==='published'?'Pasif':'Yayınla'}</button><button class="dangerMini" onclick="deleteMedia('${type}','${x.id}')">Sil</button></div></div>`; openModal('İçerik kütüphanesi',`<div class="formGrid"><h3>Görseller</h3>${imgs.map(x=>row(x,'img')).join('')||'<p>Yok</p>'}<h3>Sesler</h3>${aud.map(x=>row(x,'aud')).join('')||'<p>Yok</p>'}<h3>Belgeler/Notlar</h3>${docs.map(x=>row(x,'doc')).join('')||'<p>Yok</p>'}</div>`)}
window.togglePublish=function(type,id){let arr=type==='img'?mediaImages():type==='aud'?mediaAudio():mediaDocs(); arr=arr.map(x=>x.id===id?Object.assign(x,{publishState:x.publishState==='published'?'draft':'published'}):x); if(type==='img')saveMediaImages(arr); else if(type==='aud')saveMediaAudio(arr); else saveMediaDocs(arr); openContentLibrary(); msg('Yayın durumu güncellendi.')}
window.deleteMedia=function(type,id){confirmAction('İçerik silinsin mi?','Bu içerik tüm bağlı alanlardan kaldırılır; kırık bağlantı bırakılmaz.',()=>{let imgs=mediaImages(), aud=mediaAudio(), docs=mediaDocs(); if(type==='img')saveMediaImages(imgs.filter(x=>x.id!==id)); if(type==='aud')saveMediaAudio(aud.filter(x=>x.id!==id)); if(type==='doc')saveMediaDocs(docs.filter(x=>x.id!==id)); let cl=jd('customLessons',[]).map(l=>l.mediaId===id?Object.assign(l,{mediaId:''}):l); js('customLessons',cl); closeConfirm&&closeConfirm(false); closeModal(); msg('İçerik ve bağlantıları kaldırıldı.'); render()})}
window.openDocManager=function(){openModal('Belge / not yönetimi',`<div class="formGrid"><input id="docTitle2" placeholder="Başlık"><select id="docCat2"><option>AvOfis</option><option>Gramer</option><option>Okuma</option><option>Yazma</option><option>Göç/İltica</option></select><input id="docFile2" type="file" accept=".pdf,.doc,.docx,image/*,text/plain"><textarea id="docText2" placeholder="Belge özeti, açıklama veya uygulama içi karta dönüşecek metin"></textarea><button onclick="saveDocV2()">Taslak belge/not kaydet</button></div>`)}
window.saveDocV2=function(){const f=$id('docFile2')?.files?.[0]; const add=(dataUrl)=>{let arr=mediaDocs(); arr.unshift({id:nowid('doc'),title:$id('docTitle2').value||f?.name||'Belge',cat:$id('docCat2').value,type:f?f.type||f.name.split('.').pop():'text',desc:$id('docText2').value||'',dataUrl:dataUrl||'',publishState:'draft',t:Date.now()}); saveMediaDocs(arr); closeModal(); msg('Belge/not taslak kaydedildi.')}; if(f){const r=new FileReader(); r.onload=()=>add(String(r.result||'')); r.readAsDataURL(f)} else add('')}
window.openGrammarAdmin=function(){openModal('Gramer dersi ekle',`<div class="formGrid"><input id="gT" placeholder="Başlık"><select id="gLev"><option>A1</option><option>A2</option><option>B1</option></select><input id="gGrp" placeholder="Kategori"><textarea id="gRule" placeholder="Ana kural"></textarea><textarea id="gTr" placeholder="Türkçe anlatım"></textarea><input id="gNl" placeholder="Hollandaca örnek"><input id="gTrans" placeholder="Türkçe çeviri"><input id="gMist" placeholder="Sık hata"><input id="gEx" placeholder="Mini alıştırma"><button onclick="saveGrammarAdminV2()">Taslak ders kaydet</button></div>`)}
