/* LexLingo V5 TTS/ticker stability patch: stop on navigation, chunked speech, full ticker completion. */
(function(){
'use strict';
const V5='lex_v5_';
function $(id){return document.getElementById(id)}
function toast(msg){try{(window.gold||window.msg||function(x){console.log(x)})(msg)}catch(e){console.log(msg)}}
function enc(s){return encodeURIComponent(String(s??''))}
function cleanText(t){
  return String(t||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
}
function chunks(t, max){
  t=cleanText(t); max=max||220;
  if(!t)return [];
  const out=[]; let rest=t;
  const re=/^(.{80,220}?[.!?…。؟؛،,;:])\s+/u;
  while(rest.length>max){
    let m=rest.match(re);
    let take=m?m[1]:rest.slice(0,max);
    if(!m){
      const cut=Math.max(take.lastIndexOf(' '),take.lastIndexOf(','),take.lastIndexOf(';'),take.lastIndexOf('.'));
      if(cut>80)take=take.slice(0,cut+1);
    }
    out.push(take.trim());
    rest=rest.slice(take.length).trim();
  }
  if(rest)out.push(rest);
  return out.filter(Boolean);
}
function setSpeakerState(btn,on){
  try{
    document.querySelectorAll('.speaker').forEach(b=>b.classList.remove('playing','stop'));
    if(on&&btn)btn.classList.add('playing','stop');
  }catch(e){}
}
let oldStop=window.stopAudio;
window.__lexV5Speech={key:null,queue:[],idx:0,btn:null,timer:null,stopped:true};

window.stopAudio=function(){
  const st=window.__lexV5Speech;
  st.stopped=true; st.key=null; st.queue=[]; st.idx=0; st.btn=null;
  try{clearTimeout(st.timer)}catch(e){}
  try{if(window.speechSynthesis) window.speechSynthesis.cancel()}catch(e){}
  try{if(window.AndroidBridge&&AndroidBridge.stop) AndroidBridge.stop()}catch(e){}
  try{oldStop&&oldStop()}catch(e){}
  setSpeakerState(null,false);
};
window.stopAllAudioV5=function(){ window.stopAudio(); try{const a=$('audioPlayer'); if(a&&!a.paused){a.pause();}}catch(e){} };

function estimateMs(txt){
  const len=cleanText(txt).length;
  return Math.min(18000, Math.max(1600, len*70+450));
}
function speakChunkWithNative(text,lang,done){
  try{
    if(window.AndroidBridge&&AndroidBridge.speak){
      AndroidBridge.speak(text,lang||'nl-NL');
      setTimeout(done, estimateMs(text));
      return true;
    }
  }catch(e){}
  return false;
}
function speakNext(){
  const st=window.__lexV5Speech;
  if(st.stopped || st.idx>=st.queue.length){ window.stopAudio(); return; }
  const part=st.queue[st.idx++];
  try{
    if('speechSynthesis' in window && typeof SpeechSynthesisUtterance!=='undefined'){
      const u=new SpeechSynthesisUtterance(part.text);
      u.lang=part.lang||'nl-NL';
      u.rate=(String(u.lang).toLowerCase().startsWith('ar')?0.82:0.88);
      try{
        const voices=speechSynthesis.getVoices?speechSynthesis.getVoices():[];
        const v=voices.find(v=>(v.lang||'').toLowerCase().startsWith(String(u.lang||'').slice(0,2).toLowerCase()));
        if(v)u.voice=v;
      }catch(e){}
      u.onend=function(){ if(!st.stopped) speakNext(); };
      u.onerror=function(){ if(!st.stopped) speakNext(); };
      speechSynthesis.speak(u);
      clearTimeout(st.timer);
      st.timer=setTimeout(function(){ if(!st.stopped) speakNext(); }, estimateMs(part.text)+4000);
      return;
    }
  }catch(e){}
  if(!speakChunkWithNative(part.text, part.lang, function(){ if(!st.stopped) speakNext(); })){
    toast('Ses desteği bu cihazda kullanılamadı.');
    window.stopAudio();
  }
}
window.speak=function(text,lang,key,btn){
  text=cleanText(text);
  if(!text){toast('Seslendirilecek metin yok.'); return;}
  const st=window.__lexV5Speech;
  if(st.key===key && !st.stopped){ window.stopAudio(); return; }
  window.stopAudio();
  st.key=key||('v5-'+Date.now()); st.btn=btn||null; st.stopped=false; st.idx=0;
  setSpeakerState(btn,true);
  st.queue=chunks(text, String(lang||'').toLowerCase().startsWith('ar')?160:220).map(x=>({text:x,lang:lang||'nl-NL'}));
  speakNext();
};
window.speakSafe=function(encoded,lang,key,btn){
  let text='';
  try{text=decodeURIComponent(encoded||'')}catch(e){text=String(encoded||'')}
  window.speak(text,lang,key,btn);
};
window.speakSeqFromEncoded=function(encoded){
  let text='';
  try{text=decodeURIComponent(encoded||'')}catch(e){text=String(encoded||'')}
  const parts=cleanText(text).split(/\n+/).map(x=>x.trim()).filter(Boolean);
  window.speak(parts.join('. '),'nl-NL','v5seq',null);
};

/* Speaker icon tap policy: if anything is already speaking, tapping an active icon stops immediately. */
document.addEventListener('click',function(e){
  const sp=e.target&&e.target.closest?e.target.closest('.speaker'):null;
  if(sp && sp.classList.contains('playing')){
    e.preventDefault(); e.stopPropagation();
    window.stopAudio();
  }
},true);

/* Stop TTS when the user leaves the current screen or application context. */
function wrapStopper(name, stopMedia){
  const old=window[name];
  if(typeof old!=='function')return;
  window[name]=function(){
    try{ stopMedia?window.stopAllAudioV5():window.stopAudio(); }catch(e){}
    return old.apply(this,arguments);
  };
}
['setMode','navNext','navPrev','goStart','randomItem','openPicker','selectCategorySafe'].forEach(n=>wrapStopper(n,false));
['openExternal','openInAppPortal'].forEach(n=>wrapStopper(n,true));
window.addEventListener('pagehide',()=>window.stopAllAudioV5());
document.addEventListener('visibilitychange',()=>{ if(document.hidden) window.stopAllAudioV5(); });

/* If a card/page is replaced by render because of navigation, stop only TTS; HTML audio keeps mini-player policy from V4 unless the explicit page-leave wrappers pause it. */
(function(){
  const oldRender=window.render;
  if(typeof oldRender==='function' && !oldRender.__v5wrapped){
    const wrapped=function(){
      try{window.stopAudio()}catch(e){}
      return oldRender.apply(this,arguments);
    };
    wrapped.__v5wrapped=true;
    window.render=wrapped;
  }
})();

/* Ticker patch: do not advance to the next line until the current ticker animation fully completes.
   This removes the “half sentence” effect on long news/market lines. */
function getTickerArray(){
  try{
    const arr=(typeof window.tickerMessagesFull==='function'?window.tickerMessagesFull():[]);
    if(arr&&arr.length)return arr.map(x=>({type:x.type||'local',text:String(x.text||x||'').trim()})).filter(x=>x.text);
  }catch(e){}
  try{
    const v=JSON.parse(localStorage.getItem('lex_v3_tickerMessages')||'[]');
    if(v.length)return v.map(x=>({type:'local',text:String(x)}));
  }catch(e){}
  return [{type:'local',text:''}];
}
function tickerDuration(text){
  let base=36;
  try{ if(typeof window.tickerSpeed==='function') base=Number(window.tickerSpeed())||36; }catch(e){}
  const font=parseFloat(getComputedStyle($('tickerText')||document.body).fontSize)||14;
  return Math.max(base, Math.min(120, Math.ceil(String(text||'').length*font/38)+10));
}
window.updateTicker=function(){
  const el=$('tickerText'); if(!el)return;
  const arr=getTickerArray(); if(!arr.length)return;
  clearTimeout(window.__tickerTimer);
  let i=Number(el.dataset.idx||0)%arr.length;
  function run(){
    const item=arr[i%arr.length]; i++; el.dataset.idx=String(i%arr.length);
    el.textContent=item.text;
    el.className=item.type==='news'?'tickerNews':'tickerLocal';
    const dur=tickerDuration(item.text);
    el.style.animation='none';
    el.style.webkitAnimation='none';
    void el.offsetWidth;
    el.style.animation='tickerMove '+dur+'s linear 1';
    el.style.webkitAnimation='tickerMove '+dur+'s linear 1';
    clearTimeout(window.__tickerTimer);
    const next=function(){ el.removeEventListener('animationend',next); clearTimeout(window.__tickerTimer); window.__tickerTimer=setTimeout(run,1200); };
    el.addEventListener('animationend',next,{once:true});
    window.__tickerTimer=setTimeout(run,(dur+3)*1000);
  }
  run();
};

/* Re-run ticker after all older initializers finish. */
setTimeout(()=>{try{window.updateTicker()}catch(e){}},400);
setTimeout(()=>{try{window.updateTicker()}catch(e){}},1800);
})();




/* LexLingo V5.1 Arabic and mixed translation speech override. */
(function(){
'use strict';
function clean(t){return String(t||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();}
function dec(x){try{return decodeURIComponent(x||'')}catch(e){return String(x||'')}}
function langOf(t){
  t=String(t||'');
  if(/[\u0600-\u06ff]/.test(t))return 'ar-SA';
  if(/[ğüşöçıİĞÜŞÖÇ]/.test(t))return 'tr-TR';
  if(/\b(the|and|you|with|for|from|this|that|world|news)\b/i.test(t))return 'en-US';
  return 'nl-NL';
}
function split(t,max){t=clean(t); max=max||220; const a=[]; while(t.length>max){let s=t.slice(0,max),c=Math.max(s.lastIndexOf('.'),s.lastIndexOf('!'),s.lastIndexOf('?'),s.lastIndexOf(';'),s.lastIndexOf(','),s.lastIndexOf(' ')); if(c<80)c=max; a.push(t.slice(0,c+1).trim()); t=t.slice(c+1).trim()} if(t)a.push(t); return a}
window.speakArabicSafe=function(encodedArabic,encodedRead,key,btn){
  const ar=clean(dec(encodedArabic)), rd=clean(dec(encodedRead));
  if(ar) return window.speak(ar,'ar-SA',key,btn);
  if(rd) return window.speak(rd,'tr-TR',key,btn);
};
window.speakSeqFromEncoded=function(encoded){
  const lines=dec(encoded).split(/\n+/).map(clean).filter(Boolean);
  if(!lines.length){try{(window.gold||window.msg)('Çeviri metni yok.')}catch(e){}; return;}
  try{window.stopAudio()}catch(e){}
  const st=window.__lexV5Speech||{};
  window.__lexV5Speech=st;
  st.key='v5seq'; st.stopped=false; st.idx=0; st.btn=null;
  st.queue=[];
  lines.forEach(line=>split(line,180).forEach(part=>st.queue.push({text:part,lang:langOf(part)})));
  /* reuse V5 speak by creating a temporary chain when available */
  function next(){
    if(st.stopped||st.idx>=st.queue.length){try{window.stopAudio()}catch(e){}; return;}
    const part=st.queue[st.idx++];
    if('speechSynthesis' in window && typeof SpeechSynthesisUtterance!=='undefined'){
      const u=new SpeechSynthesisUtterance(part.text); u.lang=part.lang; u.rate=part.lang==='ar-SA'?0.82:0.88;
      try{const vs=speechSynthesis.getVoices?speechSynthesis.getVoices():[]; const v=vs.find(v=>(v.lang||'').toLowerCase().startsWith(part.lang.slice(0,2).toLowerCase())); if(v)u.voice=v;}catch(e){}
      u.onend=next; u.onerror=next; speechSynthesis.speak(u);
    }else if(window.AndroidBridge&&AndroidBridge.speak){
      AndroidBridge.speak(part.text,part.lang); setTimeout(next,Math.max(1600,part.text.length*70+500));
    }
  }
  next();
};
})();



