function findLesson(id){return grammarLessonsAll().find(x=>x.id===id)}
function spotById(id){return grammarSpotsAll().find(x=>x.id===id)}
function docById(id){return GRAMMAR_DOCS.find(x=>x.id===id)}
function patchHeaderUi(){
  const top=document.querySelector('.topActions');
  if(top&&!top.dataset.lexv2){top.dataset.lexv2='1'; top.innerHTML=`<button class="ghost" onclick="goStart()">⏮ Başa</button><button class="ghost" onclick="navPrev()">‹ Geri</button><button class="ghost" onclick="navNext()">İleri ›</button><button class="ghost" onclick="randomItem()">🔀 Rasgele</button><button class="ghost" onclick="setMode('manage')">⚙ Ayar</button>`;}
  const nav=document.querySelector('.tabs .tabsInner');
  if(nav&&!nav.dataset.lexv2){nav.dataset.lexv2='1'; nav.innerHTML=`
    <button class="tabBtn active" id="tabLearn" onclick="setMode('learn')"><span class="tabIcon">▣</span><span>Kart</span></button>
    <button class="tabBtn" id="tabWrite" onclick="setMode('write')"><span class="tabIcon">✎</span><span>Yazma</span></button>
    <button class="tabBtn" id="tabSentences" onclick="setMode('sentences')"><span class="tabIcon">💬</span><span>Cümle</span></button>
    <button class="tabBtn" id="tabParagraph" onclick="setMode('paragraph')"><span class="tabIcon">▤</span><span>Gramer</span></button>
    <button class="tabBtn" id="tabRead" onclick="setMode('read')"><span class="tabIcon">📖</span><span>Okuma</span></button>
    <button class="tabBtn" id="tabList" onclick="setMode('list')"><span class="tabIcon">☷</span><span>Liste</span></button>
    <button class="tabBtn" id="tabQuiz" onclick="setMode('quiz')"><span class="tabIcon">?</span><span>Quiz</span></button>
    <button class="tabBtn" id="tabAvOfis" onclick="setMode('avofis')"><span class="tabIcon">⚖</span><span>AvOfis</span></button>`;}
}
