window.setActiveTab=function(){ patchHeaderUi(); if(prevSetActive)try{prevSetActive()}catch(e){} document.querySelectorAll('.tabBtn').forEach(b=>b.classList.remove('active')); const map={learn:'tabLearn',write:'tabWrite',sentences:'tabSentences',paragraph:'tabParagraph',read:'tabRead',list:'tabList',quiz:'tabQuiz',avofis:'tabAvOfis',alofis:'tabAvOfis'}; const el=$id(map[currentMode2()]||''); if(el)el.classList.add('active') };
window.render=function(){ patchHeaderUi(); try{window.setActiveTab()}catch(e){} const m=currentMode2(); try{if(m==='manage')return renderManageV2(); if(m==='paragraph')return renderGrammarHub(); if(m==='read' && typeof LEX_NEWS_CAT!=='undefined' && settings.cat===LEX_NEWS_CAT)return renderNewsReadV2(); if(m==='read' && typeof LEX_AUDIO_CAT!=='undefined' && settings.cat===LEX_AUDIO_CAT)return betterRenderAudioRead(); }catch(e){console.error('v2 render route',e)} return prevRender?prevRender():undefined; };
window.addEventListener('focus',()=>{try{render()}catch(e){}});
