window.lexStopGlobalAudioV3=function(){try{const au=window.__lexActiveAudio||$v('audioPlayer'); if(au){au.pause(); au.currentTime=0}}catch(e){} try{if(window.stopAudio)stopAudio()}catch(e){} try{if('speechSynthesis' in window)speechSynthesis.cancel()}catch(e){} window.__lexActiveAudio=null; hideMini(); msg('Ses durduruldu.')};
