window.lexAudioSeekV3=function(s){const au=$v('audioPlayer')||window.__lexActiveAudio; if(au)au.currentTime=Math.max(0,Math.min(au.duration||999999,(au.currentTime||0)+s))};
window.lexAudioSpeedV3=function(){const au=$v('audioPlayer')||window.__lexActiveAudio; if(!au)return; const speeds=[.75,1,1.15,1.3,1.5]; let i=speeds.findIndex(x=>Math.abs(x-au.playbackRate)<.02); au.playbackRate=speeds[(i+1+speeds.length)%speeds.length]; msg('Hız: '+au.playbackRate+'x')};
window.lexRepeatSectionV3=function(){const au=$v('audioPlayer')||window.__lexActiveAudio; if(au){au.currentTime=0; au.play()}};
window.lexRepeatLineV3=function(i){const au=$v('audioPlayer')||window.__lexActiveAudio, lines=[...document.querySelectorAll('.lyricLine')]; if(!au||!lines[i])return; const t=parseFloat(lines[i].dataset.t); if(!isNaN(t))au.currentTime=t; au.play()};
function startSpeechToText(targetId){const SR=window.SpeechRecognition||window.webkitSpeechRecognition; if(!SR){msg('Bu cihazda konuşmayı yazıya çevirme desteği yok. Android/Chrome konuşma tanıma gerekir.'); return} const rec=new SR(); rec.lang='tr-TR'; rec.continuous=true; rec.interimResults=true; let final=''; const box=$v(targetId); if(box)box.textContent='Dinleniyor... Sistem sesi değil, cihaz mikrofonu kullanılır.'; rec.onresult=function(ev){let interim=''; for(let i=ev.resultIndex;i<ev.results.length;i++){const tx=ev.results[i][0].transcript; if(ev.results[i].isFinal)final+=tx+' '; else interim+=tx} if(box)box.textContent=(final+interim).trim()||'Dinleniyor...'; const ta=$v('eaLyrics')||$v('audLyrics2'); if(ta&&final)ta.value=(ta.value?ta.value+'\n':'')+final.trim();}; rec.onerror=function(e){msg('Yazıya çevirme hatası: '+(e.error||'izin/destek yok'))}; try{rec.start(); window.__lexStt=rec}catch(e){msg('Yazıya çevirme başlatılamadı.')}}
window.lexStartSpeechToTextV3=function(targetId){startSpeechToText(targetId)}; window.lexStopSpeechToTextV3=function(){try{if(window.__lexStt)window.__lexStt.stop()}catch(e){}};
window.betterRenderAudioRead=function(){const arr=allAudioV3(); if(!arr.length){$v('view').innerHTML=`<section class="${window.modClass?modClass():'card'}">${window.tools?tools():''}<span class="badge">Sesli içerik</span><div class="heroBox"><h3>Henüz sesli içerik yok</h3><p>Ayarlar bölümünden çoklu ses yükleme yapabilirsiniz.</p><button onclick="openAudioManager()">Ses ekle</button></div></section>`; return} try{if(typeof readPage==='undefined')window.readPage=0}catch(e){window.readPage=0} if(readPage>=arr.length)readPage=0; const item=arr[readPage]||arr[0]; const lines=parseLines(item.lyrics||''); const rows=lines.length?lines.map((l,i)=>`<div class="lyricLine" data-t="${l.t==null?'':l.t}" onclick="lexRepeatLineV3(${i})">${h(l.text)}</div>`).join(''):'<div class="lyricLine">Transkript eklenmemiş. Ayarlar > Sesli içerik bölümünden ekleyebilirsiniz.</div>'; $v('view').innerHTML=`<section class="${window.modClass?modClass():'card'} audioPro">${window.tools?tools():''}<span class="badge">Sesli içerik • ${readPage+1}/${arr.length}</span><div class="book audioBook"><div class="bookTitle">${h(item.title||'Sesli parça')}${item.builtin?' • APK içi':''}</div><audio id="audioPlayer" class="audioPlayer" controls src="${at(item.audioUrl||'')}"></audio><div class="v3TimeBar" id="audioTimeV3">00:00 / 00:00</div><div class="bookPage lyricsPage" id="lyricsPage">${rows}</div></div><div class="readerExtra"><b>Kategori:</b> ${h(item.cat||'Sesli içerik')}${item.desc?'<br><b>Açıklama:</b> '+h(item.desc):''}</div><div class="v3AudioGrid"><button class="ghost" onclick="lexAudioSeekV3(-5)">↶ 5 sn</button><button class="ghost" onclick="lexStopGlobalAudioV3()">■ Durdur</button><button class="ghost" onclick="lexAudioSeekV3(5)">5 sn ↷</button><button class="ghost" onclick="lexAudioSpeedV3()">Hız</button><button class="ghost" onclick="lexRepeatSectionV3()">Bölüm tekrar</button><button class="ghost" onclick="lexStartSpeechToTextV3('sttLiveV3')">Yazıya çevir</button><button class="ghost" onclick="lexStopSpeechToTextV3()">Yazıyı durdur</button><button class="ghost" onclick="shareText('${en((item.title||'')+'\n'+(item.lyrics||'')+'\n'+(item.desc||''))}')">↗ Paylaş</button></div><div id="sttLiveV3" class="v3SttBox">Yazıya çevirme için “Yazıya çevir” düğmesine basın. Sistem sesi doğrudan yakalanamazsa cihaz mikrofonundan duyulan ses metne çevrilir.</div><div class="moduleNav"><button class="ghost" onclick="readPage=0;render()">Başa</button><button class="ghost" onclick="readPage=Math.max(0,readPage-1);render()">Önceki</button><button class="ghost" onclick="readPage=Math.min(${arr.length-1},readPage+1);render()">Sonraki</button><button class="ghost" onclick="readPage=Math.floor(Math.random()*${arr.length});render()">Rastgele</button><button class="ghost" onclick="readPage=${arr.length-1};render()">Sona</button></div><div class="row2"><button class="ghost" onclick="openAudioEdit('${at(item.id)}')">Ayarlar/Düzenle</button><button class="ghost" onclick="setMode('manage')">Ayarlar</button></div></section>`; const audio=$v('audioPlayer'), box=$v('lyricsPage'), time=$v('audioTimeV3'); wireAudioV3(audio,item.title); if(audio)audio.ontimeupdate=function(){if(time)time.textContent=secFmt(audio.currentTime)+' / '+secFmt(audio.duration); const els=box?[...box.querySelectorAll('.lyricLine')]:[]; let lineIdx=-1; const t=audio.currentTime||0; for(let i=0;i<els.length;i++){const tt=parseFloat(els[i].dataset.t); if(!isNaN(tt)&&tt<=t)lineIdx=i} if(lineIdx<0&&audio.duration)lineIdx=Math.min(els.length-1,Math.floor((t/audio.duration)*els.length)); els.forEach((el,i)=>el.classList.toggle('active',i===lineIdx)); if(lineIdx>=0&&els[lineIdx].scrollIntoView)els[lineIdx].scrollIntoView({block:'center',behavior:'smooth'})}; };
window.openAudioManager=function(){const rows=allAudioV3().map(it=>`<div class="mediaCard ${it.builtin?'builtin':''}"><h3>${h(it.title)}</h3><div class="smallNote">${h(it.cat||'Sesli içerik')} ${it.builtin?' • APK içi':''}</div><p>${h(it.desc||'')}</p><div class="smallNote">Transkript: <code>${String((it.lyrics||'').split(/\n+/).filter(Boolean).length)}</code> satır</div><div class="mediaActions"><button class="ghost" onclick="openAudioEdit('${at(it.id)}')">Düzenle</button>${it.builtin?`<button class="danger" onclick="hideBuiltinAudioV3('${at(it.id)}')">Kaldır/Gizle</button>`:`<button class="danger" onclick="deleteAudioItemV3('${at(it.id)}')">Sil</button>`}</div></div>`).join('')||'<div class="smallNote">Henüz sesli içerik yok.</div>'; openModal('Sesli içerik yükleme / yönetim',`<div class="formGridX"><div class="full v3ManageHelp">Birden fazla ses dosyasını aynı anda seçebilirsiniz. Yükleme sırasında ortak açıklama/transkript girebilir, sonra her parçayı ayrı düzenleyebilirsiniz. “Önizleme” kaydetmeden önce ilk seçili dosyayı veya bağlantıyı kontrol eder.</div><input id="audCat2" placeholder="Kategori / etiket"><input id="audTitlePrefix2" placeholder="Başlık ön eki (isteğe bağlı)"><textarea class="full" id="audDesc2" placeholder="Ortak açıklama"></textarea><textarea class="full" id="audLyrics2" placeholder="Ortak transkript / sözler. Zamanlı kullanım: [00:12] Satır"></textarea><label class="full">Bir veya çok ses dosyası seç<input id="audFiles2" type="file" accept="audio/*" multiple></label><textarea class="full" id="audUrls2" placeholder="Alternatif: her satıra bir MP3/OGG bağlantısı"></textarea><div class="full row2"><button class="ghost" onclick="previewAudioUploadV3()">Önizleme</button><button onclick="saveAudioItemsFromForm2()">Kaydet ve yayınla</button></div><div class="full" id="audPreviewV3"></div><div class="full mediaGrid">${rows}</div></div>`)};
window.previewAudioUploadV3=function(){const files=Array.from(($v('audFiles2')||{files:[]}).files||[]); const urls=textToArray($v('audUrls2')?.value||''); const title=($v('audTitlePrefix2')?.value||'')+' '+(files[0]?.name||urls[0]||'Ses önizleme'); const desc=$v('audDesc2')?.value||''; function show(src){$v('audPreviewV3').innerHTML=`<div class="v3Preview"><b>${h(title.trim())}</b><p>${h(desc)}</p><audio class="audioPlayer" controls src="${at(src)}"></audio><div class="smallNote">Bu yalnızca önizlemedir; kaydetmek için “Kaydet ve yayınla” düğmesine basın.</div></div>`} if(files[0]){const r=new FileReader(); r.onload=()=>show(String(r.result||'')); r.readAsDataURL(files[0])} else if(urls[0])show(urls[0]); else msg('Önizleme için dosya veya bağlantı seçin.')};
window.saveAudioItemsFromForm2=function(){const files=Array.from(($v('audFiles2')||{files:[]}).files||[]); const urls=textToArray($v('audUrls2')?.value||''); if(!files.length&&!urls.length)return msg('Ses dosyası veya bağlantı ekleyin.'); const cat=$v('audCat2')?.value||'Sesli içerik'; const prefix=$v('audTitlePrefix2')?.value||''; const desc=$v('audDesc2')?.value||''; const lyrics=$v('audLyrics2')?.value||''; const now=Date.now(); Promise.all(files.map((f,i)=>new Promise(res=>{const r=new FileReader(); r.onload=()=>res({id:'AUD-'+now+'-'+i,title:(prefix?prefix+' ':'')+(f.name||'Ses').replace(/\.[^.]+$/,''),cat,desc,lyrics,audioUrl:String(r.result||''),timedLines:parseLines(lyrics),status:'published',t:Date.now()}); r.readAsDataURL(f)}))).then(items=>{urls.forEach((u,i)=>items.push({id:'AUD-'+now+'-url-'+i,title:(prefix?prefix+' ':'')+'Bağlantı '+(i+1),cat,desc,lyrics,audioUrl:u,timedLines:parseLines(lyrics),status:'published',t:Date.now()})); saveUserAudioItems(userAudioItems().concat(items)); closeModal(); setCat(typeof LEX_AUDIO_CAT!=='undefined'?LEX_AUDIO_CAT:'Sesli Parçalar'); try{mode='read'}catch(e){} render(); msg(items.length+' sesli içerik kaydedildi ve yayınlandı.')})};
window.openAudioEdit=function(id){const it=findAudioV3(id); if(!it)return msg('Ses bulunamadı.'); openModal('Sesli içerik düzenle',`<div class="formGridX"><input id="eaTitle" value="${at(it.title||'')}"><input id="eaCat" value="${at(it.cat||'')}"><textarea class="full" id="eaDesc">${h(it.desc||'')}</textarea><textarea class="full" id="eaLyrics">${h(it.lyrics||'')}</textarea><audio class="full audioPlayer" controls src="${at(it.audioUrl||'')}"></audio><div class="full row2"><button class="ghost" onclick="lexStartSpeechToTextV3('editSttV3')">Sesten yazıya dene</button><button class="ghost" onclick="lexStopSpeechToTextV3()">Durdur</button></div><div class="full v3SttBox" id="editSttV3">Konuşmayı/sesi mikrofondan dinleyerek transkripte ekleme denenebilir.</div><div class="full row2"><button class="ghost" onclick="previewAudioEditV3('${at(id)}')">Önizleme</button><button onclick="saveAudioEditV3('${at(id)}')">Kaydet ve yayınla</button></div><div class="full" id="eaPreview"></div></div>`)};
window.previewAudioEditV3=function(id){const it=findAudioV3(id)||{}; $v('eaPreview').innerHTML=`<div class="v3Preview"><b>${h($v('eaTitle').value)}</b><p>${h($v('eaDesc').value)}</p><audio class="audioPlayer" controls src="${at(it.audioUrl||'')}"></audio><div>${h(($v('eaLyrics').value||'').split(/\n+/).slice(0,3).join(' / '))}</div></div>`};
window.saveAudioEditV3=function(id){let it=findAudioV3(id); if(!it)return; const patch={title:$v('eaTitle').value||it.title,cat:$v('eaCat').value||it.cat,desc:$v('eaDesc').value||'',lyrics:$v('eaLyrics').value||'',timedLines:parseLines($v('eaLyrics').value||''),status:'published'}; if(it.builtin){const m=builtinMeta(); m[id]=Object.assign(m[id]||{},patch); saveBuiltinMeta(m)} else {const arr=userAudioItems().map(x=>x.id===id?Object.assign({},x,patch):x); saveUserAudioItems(arr)} closeModal(); render(); msg('Sesli içerik kaydedildi ve yayınlandı.')};
window.hideBuiltinAudioV3=function(id){const arr=Array.from(builtinHidden()); if(!arr.includes(id))arr.push(id); js('hiddenBuiltinAudio',arr); openAudioManager(); msg('APK içi ses gizlendi.')};
window.deleteAudioItemV3=function(id){saveUserAudioItems(userAudioItems().filter(x=>x.id!==id)); openAudioManager(); msg('Sesli içerik silindi.')};
async function fetchText(url){const urls=[url,'https://api.allorigins.win/raw?url='+encodeURIComponent(url),'https://r.jina.ai/http://'+url.replace(/^https?:\/\//,'')]; for(const u of urls){try{const r=await fetch(u,{cache:'no-store'}); if(r.ok){const tx=await r.text(); if(tx&&tx.length>20)return tx}}catch(e){}} return ''}
function parseRSS(raw,feed){try{const doc=new DOMParser().parseFromString(raw,'text/xml'); return [...doc.querySelectorAll('item, entry')].slice(0,9).map((it,i)=>{const title=(it.querySelector('title')?.textContent||'').trim(); const link=(it.querySelector('link')?.getAttribute('href')||it.querySelector('link')?.textContent||'').trim(); const desc=(it.querySelector('description')?.textContent||it.querySelector('summary')?.textContent||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim(); const pub=(it.querySelector('pubDate')?.textContent||it.querySelector('updated')?.textContent||it.querySelector('published')?.textContent||'').trim(); return title?{id:(feed.region+'-'+feed.label+'-'+(link||title||i)).replace(/[^a-z0-9]+/gi,'-').slice(0,96),title,description:desc,link,pubDate:pub,source:feed.label,region:feed.region,ts:Date.parse(pub)||Date.now()-i*60000}:null}).filter(Boolean)}catch(e){return []}}
async function fetchNewsV3(force){const key='newsItemsV3', lastKey='newsLastFetchV3'; const now=Date.now(); const cached=jd(key,[]); const interval=Math.max(5,Number(localStorage.getItem(lsPrefix()+'newsMin')||10))*60*1000; if(!force&&cached.length&&now-Number(localStorage.getItem(lsPrefix()+lastKey)||0)<interval)return cached; const cfg=jd('newsFeedConfig',{tr:true,nl:true,world:true}); let feeds=[]; if(cfg.tr!==false)feeds=feeds.concat(V3_NEWS_FEEDS.TR); if(cfg.nl!==false)feeds=feeds.concat(V3_NEWS_FEEDS.NL); if(cfg.world!==false)feeds=feeds.concat(V3_NEWS_FEEDS.WORLD); let all=[]; for(const f of feeds){const raw=await fetchText(f.url); if(raw)all=all.concat(parseRSS(raw,f))} const map=new Map(); all.sort((x,y)=>(y.ts||0)-(x.ts||0)).forEach(n=>{if(!map.has(n.id)&&n.title)map.set(n.id,n)}); let arr=[...map.values()]; const result=[]; ['TR','NL','WORLD'].forEach(region=>{result.push(...arr.filter(x=>x.region===region).slice(0,6))}); if(result.length){js(key,result); js('newsItemsV2',result); js('newsItems',result); localStorage.setItem(lsPrefix()+lastKey,String(now)); return result} return cached}
window.fetchNewsItemsV3=fetchNewsV3; window.fetchNewsItemsV2=fetchNewsV3; window.fetchNewsItems=fetchNewsV3;
async function fetchStocksV3(force){const key='stockItemsV3', lastKey='stockLastFetchV3'; const now=Date.now(); const cached=jd(key,[]); if(!force&&cached.length&&now-Number(localStorage.getItem(lsPrefix()+lastKey)||0)<5*60*1000)return cached; const symbols=['XU100.TR'].concat(textToArray(localStorage.getItem(lsPrefix()+'stockSymbols')||'')); const uniq=[...new Set(symbols.map(s=>s.toUpperCase().replace(/\.IS$/,'.TR')))]; const out=[]; for(const sym of uniq){const stooq=sym.includes('.')?sym.toLowerCase():(sym.toLowerCase()+'.tr'); const raw=await fetchText('https://stooq.com/q/l/?s='+encodeURIComponent(stooq)+'&f=sd2t2ohlcv&h&e=csv'); if(raw){const lines=raw.trim().split(/\n/); if(lines.length>1){const hds=lines[0].split(','), vals=lines[1].split(','); const obj={}; hds.forEach((k,i)=>obj[k]=vals[i]); if(obj.Close&&obj.Close!=='N/D')out.push({symbol:sym.replace('.TR',''),price:obj.Close,date:obj.Date,time:obj.Time,source:'Stooq'})}}} if(out.length){js(key,out); localStorage.setItem(lsPrefix()+lastKey,String(now))} return out.length?out:cached}
function tickerMessagesFullV3(){const local=(jd('tickerMessages',null)|| (window.tickerMessages?tickerMessages():[])).map(x=>({type:'local',text:String(x)})); const news=jd('newsItemsV3',jd('newsItemsV2',[])); const latest=['TR','NL','WORLD'].map(r=>news.filter(n=>n.region===r).sort((a,b)=>(b.ts||0)-(a.ts||0))[0]).filter(Boolean).map(n=>({type:'news',text:n.title})); const stocks=jd('stockItemsV3',[]).map(s=>({type:'stock',text:(s.symbol==='XU100'?'BIST 100':s.symbol)+': '+s.price+(s.time?' • '+s.time:'')})); return local.concat(latest,stocks).filter(x=>String(x.text||'').trim())}
window.updateTicker=function(){applyTickerPunto(); const el=$v('tickerText'); if(!el)return; const arr=tickerMessagesFullV3(); if(!arr.length)return; clearTimeout(window.__tickerTimerV3); let i=Number(el.dataset.v3idx||0)||0; const speed=Math.max(12,Math.min(90,Number(localStorage.getItem(lsPrefix()+'tickerSpeed')||30))); function run(){const item=arr[i%arr.length]; el.dataset.v3idx=String((i+1)%arr.length); el.textContent=item.text; el.className=item.type==='stock'?'tickerStock':(item.type==='news'?'tickerNews':'tickerLocal'); el.style.animation='none'; void el.offsetWidth; el.style.animation='tickerMove '+speed+'s linear 1'; i++; window.__tickerTimerV3=setTimeout(run,speed*1000+5000)} run()};
window.openTickerManager=function(){const cfg=jd('newsFeedConfig',{tr:true,nl:true,world:true}); const msgs=(jd('tickerMessages',null)|| (window.tickerMessages?tickerMessages():[])).join('\n'); const speed=Math.max(12,Math.min(90,Number(localStorage.getItem(lsPrefix()+'tickerSpeed')||30))); const punto=Number(localStorage.getItem(lsPrefix()+'tickerPunto')||14.5); const stocks=localStorage.getItem(lsPrefix()+'stockSymbols')||'THYAO, ASELS'; const min=Number(localStorage.getItem(lsPrefix()+'newsMin')||10); openModal('Kayan yazı, haber ve borsa',`<div class="formGrid"><div class="goldNote">Haber ve borsa satırları manuel AvOfis yazısıyla aynı tek satırlık ince formatta akar. Punto ayarı yazıyı büyütüp küçültür.</div><label>Kayan yazılar<textarea id="tickerInput">${h(msgs)}</textarea></label><label>Hız: <b id="tickerSpeedText">${speed} sn</b><input id="tickerSpeedRange" type="range" min="12" max="90" value="${speed}" oninput="$v('tickerSpeedText').textContent=this.value+' sn'"></label><label>Punto: <b id="tickerPuntoText">${punto} px</b><input id="tickerPuntoRange" type="range" min="10" max="24" step="0.5" value="${punto}" oninput="$v('tickerPuntoText').textContent=this.value+' px'"></label><label>Otomatik haber güncelleme (dakika)<input id="newsMinInput" type="number" min="5" value="${min}"></label><label><input type="checkbox" id="feedTr" ${cfg.tr!==false?'checked':''}> Türkiye son dakika</label><label><input type="checkbox" id="feedNl" ${cfg.nl!==false?'checked':''}> Hollanda son dakika</label><label><input type="checkbox" id="feedWorld" ${cfg.world!==false?'checked':''}> Dünya haberleri</label><label>Hisse senetleri (virgülle; BIST 100 daima eklenir)<input id="stockSymbolsInput" value="${h(stocks)}"></label><div class="row2"><button onclick="saveTickerSettingsV3()">Kaydet</button><button class="ghost" onclick="refreshFeedsV3()">Haber/Borsa yenile</button></div></div>`)};
