window.renderNewsReadV2=function(){fetchNewsV3(false).then(()=>{try{updateTicker()}catch(e){}}); const arr=jd('newsItemsV3',jd('newsItemsV2',[])); const sections=[['TR','Türkiye son dakika'],['NL','Hollanda son dakika'],['WORLD','Dünya son dakika']]; const html=sections.map(([r,label])=>{const items=arr.filter(x=>x.region===r).sort((a,b)=>(b.ts||0)-(a.ts||0)).slice(0,6); return `<div class="v3NewsSection"><h3>${label}</h3>${items.map((n,i)=>`<article class="newsItem"><div class="newsRegion">${h(n.source)} • ${i===0?'En güncel':'Geçmiş haber'} • ${h(n.pubDate||'')}</div><div class="newsTitle">${h(n.title)}</div>${n.description?`<div class="value">${h(n.description)}</div>`:''}<div class="row2"><button class="ghost" onclick="shareText('${en((n.title||'')+'\n'+(n.description||''))}')">↗ Paylaş</button><button class="ghost" onclick="openExternal('${at(n.link||'')}')">Kaynağı aç</button></div></article>`).join('') || '<p>Bu kategori için haber yükleniyor.</p>'}</div>`}).join(''); const stocks=jd('stockItemsV3',[]); const stockHtml=stocks.length?`<div class="v3NewsSection"><h3>Borsa / seçili hisseler</h3>${stocks.map(s=>`<div class="v3StockLine"><b>${h(s.symbol==='XU100'?'BIST 100':s.symbol)}:</b> ${h(s.price)} <span>${h((s.date||'')+' '+(s.time||''))}</span></div>`).join('')}</div>`:''; $v('view').innerHTML=`<section class="${window.modClass?modClass():'card'}">${window.tools?tools():''}<span class="badge">Son dakika ve piyasa</span>${html}${stockHtml}<div class="row2"><button onclick="refreshFeedsV3()">↻ Güncelle</button><button class="ghost" onclick="openTickerManager()">Ayar</button></div></section>`};
function openExternalShell(url){url=String(url||''); if(!url)return msg('Bağlantı yok.'); openModal('Bağlantı / uygulamaya dönüş',`<div class="formGrid"><div class="goldNote">Uygulamadan kopmamak için bağlantı bu pencere içinde açılır. Site iframe kabul etmezse “Tarayıcıda aç” düğmesini kullanıp Android geri tuşuyla dönebilirsiniz.</div><div class="row2"><button onclick="closeModal()">Uygulamaya dön</button><button class="ghost" onclick="try{window.__lexNativeOpen('${at(url)}')}catch(e){location.href='${at(url)}'}">Tarayıcıda aç</button></div><iframe class="v3ExternalFrame" src="${at(url)}"></iframe></div>`)}
const nativeOpen=window.open?window.open.bind(window):null; window.__lexNativeOpen=function(url){if(nativeOpen)nativeOpen(url,'_blank'); else location.href=url}; window.openExternal=openExternalShell; document.addEventListener('click',function(ev){const link=ev.target&&ev.target.closest?ev.target.closest('a[href]'):null; if(link&&/^https?:/i.test(link.href)){ev.preventDefault(); openExternalShell(link.href)}},true);
