const oldSaveAvofisPage=window.saveAvofisPage; window.saveAvofisPage=function(){if(oldSaveAvofisPage)oldSaveAvofisPage(); else msg('Sayfa kaydedildi.'); msg('Bilgi/sayfa kaydedildi ve yayınlandı.')};
function enablePinch(){let start=0,target=null; document.addEventListener('touchstart',e=>{if(e.touches&&e.touches.length===2){const dx=e.touches[0].clientX-e.touches[1].clientX, dy=e.touches[0].clientY-e.touches[1].clientY; start=Math.hypot(dx,dy); target=e.target.closest&&e.target.closest('img,.card,.book,.value,.spotImage,.spotImg,.mediaThumb,p,article'); if(target){target.style.transition='transform .12s ease'; target.classList.add('pinchZooming')}}},{passive:true}); document.addEventListener('touchmove',e=>{if(start&&target&&e.touches.length===2){const dx=e.touches[0].clientX-e.touches[1].clientX, dy=e.touches[0].clientY-e.touches[1].clientY; const sc=Math.max(1,Math.min(2.4,Math.hypot(dx,dy)/start)); target.style.transform='scale('+sc.toFixed(2)+')'}},{passive:true}); document.addEventListener('touchend',()=>{if(target){const t=target; setTimeout(()=>{t.style.transition='transform .45s ease'; t.style.transform=''; t.classList.remove('pinchZooming')},1400)} start=0; target=null},{passive:true})}
