const prevRender=window.render; window.render=function(){ensureCss(); try{if(window.patchHeaderUi)patchHeaderUi(); if(window.setActiveTab)setActiveTab()}catch(e){} const m=currentMode(); try{if(m==='read'&&typeof LEX_AUDIO_CAT!=='undefined'&&settings.cat===LEX_AUDIO_CAT)return betterRenderAudioRead(); if(m==='read'&&typeof LEX_NEWS_CAT!=='undefined'&&settings.cat===LEX_NEWS_CAT)return renderNewsReadV2()}catch(e){console.error('v3 route',e)} return prevRender?prevRender():undefined};
