window.saveAudioItemsFromFormV4=async function(){
 const files=Array.from(($v('audFiles4')||{files:[]}).files||[]), urls=arrText($v('audUrls4')?.value||'');
 if(!files.length&&!urls.length)return msg('Ses dosyası veya bağlantı ekleyin.');
 const cat=$v('audCat4')?.value||catAudio(), prefix=$v('audTitlePrefix4')?.value||'', desc=$v('audDesc4')?.value||'', lyrics=$v('audLyrics4')?.value||'', now=Date.now();
 const items=[];
 try{
   for(let i=0;i<files.length;i++){
     const f=files[i]; const id='AUDV4-'+now+'-'+i, blobKey=id+'-'+(f.name||'audio');
     await putBlobV4(blobKey,f);
     items.push({id,title:(prefix?prefix+' ':'')+(f.name||'Ses').replace(/\.[^.]+$/,''),cat,desc,lyrics,blobKey,mime:f.type||'audio/*',timedLines:parseLinesV4(lyrics),status:'published',t:Date.now()});
   }
   urls.forEach((u,i)=>items.push({id:'AUDV4-'+now+'-url-'+i,title:(prefix?prefix+' ':'')+'Bağlantı '+(i+1),cat,desc,lyrics,audioUrl:u,timedLines:parseLinesV4(lyrics),status:'published',t:Date.now()}));
   saveAudioV4Items(audioV4Items().concat(items));
   closeModal(); setAudioCat(); try{render()}catch(e){} msg(items.length+' sesli içerik kaydedildi ve yayınlandı.');
 }catch(e){msg('Ses kaydedilemedi: '+(e&&e.message?e.message:e)+'. Dosya çok büyükse cihaz depolama iznini/alanını kontrol edin.')}
};
window.deleteAudioItemV4=async function(id){
 const arr=audioV4Items(), item=arr.find(x=>x.id===id);
 if(item&&item.blobKey)await delBlobV4(item.blobKey);
 saveAudioV4Items(arr.filter(x=>x.id!==id));
 openAudioManager(); msg('Sesli içerik silindi.')
};
