/* ---------- Audio read mode + upload + STT ---------- */
function miniV4(){let bar=$v('v4MiniFix'); if(bar)return bar; bar=document.createElement('div'); bar.id='v4MiniFix'; bar.className='v4MiniFix'; bar.innerHTML=`<div class="title" id="v4MiniTitle">Ses çalıyor</div><button class="ghost" onclick="lexStopGlobalAudioV4()">■ Durdur</button><button class="ghost" onclick="setAudioCatV4(); if(window.setMode)setMode('read'); else if(window.render)render()">Aç</button>`; document.body.appendChild(bar); return bar}
function showMiniV4(title){const bar=miniV4(), t=$v('v4MiniTitle'); if(t)t.textContent=title||'Ses çalıyor'; bar.classList.add('show')}
function hideMiniV4(){const bar=$v('v4MiniFix'); if(bar)bar.classList.remove('show')}
window.lexStopGlobalAudioV4=function(){try{if(window.__lexActiveAudio){window.__lexActiveAudio.pause(); window.__lexActiveAudio.currentTime=0}}catch(e){} try{if(window.lexStopGlobalAudioV3)lexStopGlobalAudioV3()}catch(e){} stopSpeechV4(); hideMiniV4()};
function wireAudioV4(audio,title){if(!audio)return; window.__lexActiveAudio=audio; audio.addEventListener('play',()=>showMiniV4(title)); audio.addEventListener('pause',()=>{setTimeout(()=>{if(!audio||audio.paused)hideMiniV4()},250)}); audio.addEventListener('ended',hideMiniV4)}
window.lexAudioSeekV4=function(s){const a=$v('audioPlayer')||window.__lexActiveAudio; if(a)a.currentTime=Math.max(0,(a.currentTime||0)+Number(s||0))};
window.lexAudioSpeedV4=function(){const a=$v('audioPlayer')||window.__lexActiveAudio; if(!a)return; const speeds=[.75,1,1.15,1.3,1.5]; let i=speeds.findIndex(x=>Math.abs(x-a.playbackRate)<.02); a.playbackRate=speeds[(i+1+speeds.length)%speeds.length]; msg('Hız: '+a.playbackRate+'x')};
window.lexRepeatSectionV4=function(){const a=$v('audioPlayer')||window.__lexActiveAudio; if(a){a.currentTime=0; a.play()}};
window.lexRepeatLineV4=function(i){const a=$v('audioPlayer')||window.__lexActiveAudio, lines=[...document.querySelectorAll('.lyricLine')]; if(!a||!lines[i])return; const t=parseFloat(lines[i].dataset.t); if(!isNaN(t))a.currentTime=t; a.play()};
