/* -------- Bounded pinch zoom and double-tap reset -------- */
function enableBoundedPinchV6(){
 let target=null,start=0,lastTap=0,resetTimer=null;
 const dist=t=>Math.hypot(t[0].clientX-t[1].clientX,t[0].clientY-t[1].clientY);
 const reset=el=>{if(!el)return; el.classList.add('v6ZoomReset'); el.style.setProperty('--v6zoom','1'); setTimeout(()=>{el.classList.remove('v6Zooming','v6ZoomReset'); el.style.removeProperty('--v6zoom')},300)};
 document.addEventListener('touchstart',e=>{if(e.touches.length===2){target=e.target.closest('.modalBox,.card,.bookPage,.v6AudioCard,#view')||$('view')||document.body; start=dist(e.touches); target.classList.add('v6Zooming'); clearTimeout(resetTimer)}}, {passive:false});
 document.addEventListener('touchmove',e=>{if(target&&e.touches.length===2){e.preventDefault(); const z=Math.max(1,Math.min(1.85,dist(e.touches)/Math.max(30,start))); target.style.setProperty('--v6zoom',z.toFixed(2));}}, {passive:false});
 document.addEventListener('touchend',()=>{if(target){clearTimeout(resetTimer); const t=target; resetTimer=setTimeout(()=>reset(t),1400); target=null}}, {passive:true});
 document.addEventListener('click',e=>{const now=Date.now(); if(now-lastTap<360){const el=e.target.closest('.modalBox,.card,.bookPage,.v6AudioCard,#view'); if(el){e.preventDefault(); reset(el)}} lastTap=now;}, true);
}

/* -------- Arabic Turkish transliteration normalization -------- */
function fixArabicReadV6(txt){
 let s=String(txt||'').trim(); if(!s)return s;
 s=s.replace(/[âā]/gi,'a').replace(/[îī]/gi,'i').replace(/[ûū]/gi,'u').replace(/[ḫḥ]/gi,'h').replace(/[ṣ]/gi,'s').replace(/[ḍ]/gi,'d').replace(/[ṭ]/gi,'t').replace(/[ẓ]/gi,'z').replace(/[ʿ‘’`´]/g,'').replace(/\s*-\s*/g,' ').replace(/\s+/g,' ');
 const reps=[
  [/\bBismi\s+(?:el\s*)?lahi\s+er\s+rahmani\s+er\s+rahimi\b/gi,'Bismillahirrahmanirrahim'],
  [/\bBismi\s+illahi\s+rrahmani\s+rrahimi?\b/gi,'Bismillahirrahmanirrahim'],
  [/\bBismillahi\s+rrahmani\s+rrahimi?\b/gi,'Bismillahirrahmanirrahim'],
  [/\bel\s*lahi\b/gi,'illahi'],[/\ber\s*rahmani\b/gi,'rrahmani'],[/\ber\s*rahimi\b/gi,'rrahim'],[/\ber\s*rahim\b/gi,'rrahim'],
  [/\bel\s*hamdu\s+lillahi\s+rabbil\s+alem[iı]n\b/gi,'Elhamdulillahi Rabbilalemin'],
  [/\bmaliki\s+yevmi\s+d\s*din\b/gi,'Maliki yevmiddin'],[/\biyyake\s+nabudu\s+ve\s+iyyake\s+nestein\b/gi,'İyyake nabudu ve iyyake nestein'],
  [/\bihdina\s+s\s*siratal\s+mustakim\b/gi,'İhdinessiratal mustakim'],[/\bsiratallezine\b/gi,'Siratallezine'],[/\baleyhim\b/gi,'aleyhim'],[/\bgayril\b/gi,'ğayril']
 ];
 reps.forEach(([a,b])=>{s=s.replace(a,b)});
 s=s.replace(/Bismi\s+illahi/gi,'Bismillahi').replace(/illahi\s+rrahmani\s+rrahim/gi,'illahirrahmanirrahim').replace(/\s+/g,' ').trim();
 return s;
}
const oldRead=window.readByLang;
window.readByLang=function(x,k){const val=oldRead?oldRead(x,k):''; return String(k||'').toUpperCase()==='AR'?fixArabicReadV6(val):val};
const oldArabicSpeak=window.speakArabicSafe;
window.speakArabicSafe=function(encodedArabic,encodedRead,key,btn){const ar=dec(encodedArabic||'').replace(/[\u064B-\u065F\u0670]/g,'').trim(); const rd=fixArabicReadV6(dec(encodedRead||'')); if(ar&&window.speak)return window.speak(ar,'ar-SA',key,btn); if(window.speak)return window.speak(rd,'tr-TR',key,btn); if(oldArabicSpeak)return oldArabicSpeak(enc(ar),enc(rd),key,btn)};
