/* -------- Cleaner audio reader with usable scroll, Arabic STT and necessary controls only -------- */
function parseLinesV6(txt){return String(txt||'').split(/\n+/).map((line,i)=>{line=line.trim(); if(!line)return null; const m=line.match(/^\[?(\d{1,2}):(\d{2})(?:[.,](\d{1,3}))?\]?\s*(.*)$/); return m?{t:Number(m[1])*60+Number(m[2])+(Number(m[3]||0)/1000),text:m[4]||'',i}:{t:null,text:line,i}}).filter(Boolean)}
function sec(s){s=Number(s); if(!isFinite(s)||s<0)s=0; return String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.floor(s%60)).padStart(2,'0')}
function openAudioDbV6(){return new Promise((res,rej)=>{try{const r=indexedDB.open('lexlingo_audio_store_v4',1); r.onupgradeneeded=e=>{const db=e.target.result;if(!db.objectStoreNames.contains('files'))db.createObjectStore('files')}; r.onsuccess=e=>res(e.target.result); r.onerror=e=>rej(e.target.error)}catch(e){rej(e)}})}
function getBlobV6(key){return openAudioDbV6().then(db=>new Promise((res,rej)=>{const tx=db.transaction('files','readonly'), rq=tx.objectStore('files').get(key); rq.onsuccess=()=>{db.close();res(rq.result||null)}; rq.onerror=e=>{db.close();rej(e.target.error)}}))}
