 $('view').innerHTML=`<section class="${window.modClass?modClass():'card'}">${window.tools?tools():''}<span class="badge">Son dakika haberleri</span>${detail}${sections}${finance}<div class="row2"><button onclick="refreshFeedsV8()">↻ Güncelle</button><button class="ghost" onclick="openTickerManager()">Ayar</button></div></section>`;
