/* -------- Category-based audio: no standalone audio category -------- */
function parseLines(tx){return String(tx||'').split(/\n+/).map((line,i)=>{line=line.trim(); if(!line)return null; const m=line.match(/^\[?(\d{1,2}):(\d{2})(?:[.,](\d{1,3}))?\]?\s*(.*)$/); return m?{t:Number(m[1])*60+Number(m[2])+(Number(m[3]||0)/1000),text:m[4]||'',i}:{t:null,text:line,i}}).filter(Boolean)}
function sec(t){t=Number(t); if(!isFinite(t))return '00:00'; const m=Math.floor(t/60), s=Math.floor(t%60); return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')}
function openDbV8(name,store){return new Promise((resolve,reject)=>{try{const req=indexedDB.open(name,1); req.onupgradeneeded=e=>{const db=e.target.result;if(!db.objectStoreNames.contains(store))db.createObjectStore(store)}; req.onsuccess=e=>resolve(e.target.result); req.onerror=e=>reject(e.target.error||new Error('IndexedDB açılamadı'))}catch(e){reject(e)}})}
function dbPutV8(key,blob){return openDbV8('lexlingo_audio_store_v8','files').then(db=>new Promise((res,rej)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(blob,key);tx.oncomplete=()=>{db.close();res()};tx.onerror=e=>{db.close();rej(e.target.error)}}))}
function dbGetV8(key,dbName){return openDbV8(dbName||'lexlingo_audio_store_v8','files').then(db=>new Promise((res,rej)=>{const tx=db.transaction('files','readonly');const rq=tx.objectStore('files').get(key);rq.onsuccess=()=>{db.close();res(rq.result||null)};rq.onerror=e=>{db.close();rej(e.target.error)}})).catch(()=>null)}
function dbDelV8(key){return openDbV8('lexlingo_audio_store_v8','files').then(db=>new Promise((res,rej)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').delete(key);tx.oncomplete=()=>{db.close();res()};tx.onerror=e=>{db.close();rej(e.target.error)}})).catch(()=>{})}
function userAudioV8(){return jget('catAudioV8',[])}
function saveUserAudioV8(a){jset('catAudioV8',a||[])}
function hiddenBuiltinV8(){return new Set(jget('hiddenBuiltinAudioV8',[]))}
function hideBuiltinV8(id){const s=hiddenBuiltinV8(); s.add(id); jset('hiddenBuiltinAudioV8',[...s])}
function mapAudioCatV8(it){
 const text=[it.title,it.cat,it.audioUrl,it.desc].join(' ').toLowerCase();
 if(/mushaf|surah|sure|qur|kur.?an|cevsen|cevşen|tesbihat|namaz/.test(text))return QURAN_CAT;
 if((it.cat||'')===catAudio())return QURAN_CAT;
 return it.cat||'Genel';
}
function allAudioBaseV8(){
 let prev=[]; try{prev=window.allAudioV4?window.allAudioV4():(window.audioItems2?window.audioItems2():[])}catch(e){prev=[]}
 const hid=hiddenBuiltinV8();
 const built=prev.map(x=>Object.assign({},x,{cat:mapAudioCatV8(x),_base:x._src||'legacy'})).filter(x=>!hid.has(x.id));
 const ours=V8_QURAN_AUDIO.concat(userAudioV8()).map(x=>Object.assign({},x,{cat:mapAudioCatV8(x),_base:x._src||'v8'})).filter(x=>!hid.has(x.id));
 const seen=new Set(), out=[];
 built.concat(ours).forEach(x=>{if(!x||!x.id||seen.has(x.id))return; seen.add(x.id); out.push(x)});
 return out;
}
function audioForCatV8(cat){cat=cat||catNow(); if(cat==='ALL')return []; return allAudioBaseV8().filter(x=>mapAudioCatV8(x)===cat)}
async function resolveAudioV8(it){
 if(!it)return ''; if(it.blobKeyV8){const b=await dbGetV8(it.blobKeyV8,'lexlingo_audio_store_v8'); if(b){window.__lexV8BlobUrls=window.__lexV8BlobUrls||{}; if(!window.__lexV8BlobUrls[it.blobKeyV8])window.__lexV8BlobUrls[it.blobKeyV8]=URL.createObjectURL(b); return window.__lexV8BlobUrls[it.blobKeyV8]}}
 if(it.blobKey){const b=await dbGetV8(it.blobKey,'lexlingo_audio_store_v4'); if(b){window.__lexV8BlobUrls=window.__lexV8BlobUrls||{}; if(!window.__lexV8BlobUrls[it.blobKey])window.__lexV8BlobUrls[it.blobKey]=URL.createObjectURL(b); return window.__lexV8BlobUrls[it.blobKey]}}
 return it.audioUrl||it.dataUrl||'';
}
function saveAudioMetaV8(id,patch){let arr=userAudioV8(), changed=false; arr=arr.map(x=>x.id===id?(changed=true,Object.assign({},x,patch)):x); if(changed){saveUserAudioV8(arr);return} let p=jget('builtinAudioMetaV8',{}); p[id]=Object.assign(p[id]||{},patch); jset('builtinAudioMetaV8',p)}
function mergedAudioMetaV8(it){const p=jget('builtinAudioMetaV8',{}); return Object.assign({},it,p[it.id]||{})}
window.lexStopAllMediaV8=function(){
 try{document.querySelectorAll('audio,video').forEach(a=>{try{a.pause()}catch(e){}})}catch(e){}
 try{if(window.speechSynthesis)speechSynthesis.cancel()}catch(e){}
 try{if(window.lexStopSpeechToTextV6)lexStopSpeechToTextV6()}catch(e){}
 try{if(window.lexStopGlobalAudioV4)lexStopGlobalAudioV4()}catch(e){}
 try{if(window.lexStopGlobalAudioV3)lexStopGlobalAudioV3()}catch(e){}
};
window.lexAudioSeekV8=s=>{const a=$('v8AudioPlayer')||window.__lexV8Audio; if(a)a.currentTime=Math.max(0,Math.min(a.duration||999999,(a.currentTime||0)+Number(s||0)))};
window.lexAudioSpeedV8=()=>{const a=$('v8AudioPlayer')||window.__lexV8Audio; if(!a)return; const sp=[.75,1,1.15,1.3,1.5]; let i=sp.findIndex(x=>Math.abs(x-a.playbackRate)<.02); a.playbackRate=sp[(i+1+sp.length)%sp.length]; msg('Hız: '+a.playbackRate+'x')};
window.lexAudioRepeatV8=()=>{const a=$('v8AudioPlayer')||window.__lexV8Audio; if(a){a.currentTime=0;a.play().catch(()=>{})}};
