async function wireAudioPanelV8(it){
 const audio=$('v8AudioPlayer'), box=$('v8Lyrics'), time=$('v8Time'); if(!audio||!it)return; window.lexStopAllMediaV8(); window.__lexV8Audio=audio; const src=await resolveAudioV8(it); audio.src=src; audio.load&&audio.load();
 audio.addEventListener('play',()=>{document.querySelectorAll('audio').forEach(a=>{if(a!==audio)try{a.pause()}catch(e){}})});
 audio.addEventListener('pause',()=>{}); audio.addEventListener('ended',()=>{});
 let userScroll=0; if(box)box.addEventListener('scroll',()=>userScroll=Date.now(),{passive:true});
 audio.ontimeupdate=()=>{if(time)time.textContent=sec(audio.currentTime)+' / '+sec(audio.duration); const els=box?[...box.querySelectorAll('.v8LyricLine')]:[]; let ix=-1,t=audio.currentTime||0; for(let i=0;i<els.length;i++){const tt=parseFloat(els[i].dataset.t); if(!isNaN(tt)&&tt<=t)ix=i} if(ix<0&&audio.duration)ix=Math.min(els.length-1,Math.floor((t/audio.duration)*els.length)); els.forEach((el,i)=>el.classList.toggle('active',i===ix)); if(ix>=0&&Date.now()-userScroll>4200){const el=els[ix]; box.scrollTo({top:Math.max(0,el.offsetTop-box.clientHeight/2+el.clientHeight/2),behavior:'smooth'})}};
}
