window.lexSaveUploadV8=async function(){const files=[...(($('v8AudFiles')||{files:[]}).files||[])]; if(!files.length)return msg('Ses dosyası seçin.'); const cat=catNow(), title=$('v8AudTitle')?.value||'', desc=$('v8AudDesc')?.value||'', lyrics=$('v8AudLyrics')?.value||'', now=Date.now(); const arr=userAudioV8(); for(let i=0;i<files.length;i++){const f=files[i], id='V8AUD-'+now+'-'+i, key=id+'-'+(f.name||'audio'); await dbPutV8(key,f); arr.push({id,title:(title?title+' ':'')+(f.name||'Ses').replace(/\.[^.]+$/,''),cat,desc,lyrics,blobKeyV8:key,mime:f.type||'audio/*',_src:'v8',t:Date.now()})} saveUserAudioV8(arr); msg(files.length+' ses bu kategoriye kaydedildi.'); render()};
