window.lexStartSttV8=function(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition, box=$('v8SttBox'); if(!SR){if(box)box.textContent='Bu cihaz konuşma tanımayı desteklemiyor.'; return} try{lexStopSttV8()}catch(e){} const rec=new SR(); rec.lang=$('v8SttLang')?.value||'ar-SA'; rec.continuous=true; rec.interimResults=true; window.__lexV8SttFinal=''; rec.onstart=()=>{if(box)box.textContent='Dinleniyor...'}; rec.onresult=e=>{let inter=''; for(let i=e.resultIndex;i<e.results.length;i++){const tx=e.results[i][0].transcript; if(e.results[i].isFinal)window.__lexV8SttFinal+=tx+' '; else inter+=tx} if(box)box.textContent=(window.__lexV8SttFinal+inter).trim()}; rec.onerror=e=>{if(box)box.textContent='Hata: '+(e.error||'izin/destek yok')}; rec.onend=()=>{if(window.__lexV8SttRunning)setTimeout(()=>{try{rec.start()}catch(e){}},650)}; window.__lexV8SttRunning=true; window.__lexV8Stt=rec; try{rec.start()}catch(e){if(box)box.textContent='Başlatılamadı: '+(e.message||e)}}; 
