/* -------- Backup advice in settings -------- */
function appendBackupPanelV8(){
 if(modeNow()!=='manage'||$('v8BackupPanel'))return; const v=$('view'); if(!v)return;
 const div=document.createElement('section'); div.id='v8BackupPanel'; div.className='v8BackupPanel';
 div.innerHTML=`<h3>Yedekleme tavsiyesi</h3><p>Giriş yapan kullanıcıların kelime ilerlemesi, quiz puanı, özel kategori, ses açıklaması, transkript ve ayar bilgilerini düzenli yedeklemesi önerilir.</p><ul><li>Telefonda <b>LexLingo</b> adlı klasör açıp JSON yedeğini oraya kaydedebilirsiniz.</li><li>Bulut klasörünüze yüklerseniz uygulamayı kaldırıp tekrar kursanız veya başka cihazdan kullansanız bile yedek dosyasını geri yükleyebilirsiniz.</li><li>Bulut yedek JSON bağlantısını aşağıya yazarsanız uygulama o bağlantıdan geri yüklemeyi deneyebilir.</li></ul><input id="v8BackupUrl" placeholder="Bulut yedek JSON bağlantısı" value="${h(localStorage.getItem(P()+'backupUrlV8')||'')}"><div class="v8BackupActions"><button onclick="lexExportBackupV8()">Yedeği indir</button><button class="ghost" onclick="lexImportBackupFileV8()">Dosyadan geri yükle</button><button class="ghost" onclick="lexSaveBackupUrlV8()">Linki kaydet</button><button class="ghost" onclick="lexImportBackupUrlV8()">Linkten geri yükle</button></div><input id="v8BackupFile" type="file" accept="application/json,.json"><div class="v8Meta">Zaman zaman Ayarlar’a girdiğinizde yedekleme yapmanız hatırlatılır. Büyük ses dosyaları cihazda kalabilir; kritik transkript ve performans bilgileri JSON yedeğinde korunur.</div>`;
 v.appendChild(div);
 const last=Number(localStorage.getItem(P()+'backupReminderLastV8')||0); if(Date.now()-last>7*24*3600*1000){msg('Yedekleme önerisi: Ayarlar bölümünden LexLingo yedeği alabilirsiniz.'); localStorage.setItem(P()+'backupReminderLastV8',String(Date.now()))}
}
window.lexExportBackupV8=function(){const data={version:8,exportedAt:new Date().toISOString(),localStorage:{}}; Object.keys(localStorage).forEach(k=>{if(k.startsWith(P()))data.localStorage[k]=localStorage.getItem(k)}); const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}); const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='LexLingo_yedek_v8_'+new Date().toISOString().slice(0,10)+'.json'; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),3000); msg('Yedek indirildi. LexLingo klasörüne veya bulut klasörünüze kaydedin.')};
window.lexImportBackupFileV8=function(){const f=$('v8BackupFile')?.files?.[0]; if(!f)return msg('Önce JSON dosyası seçin.'); const r=new FileReader(); r.onload=()=>{try{const d=JSON.parse(String(r.result||'{}')); Object.entries(d.localStorage||{}).forEach(([k,v])=>{if(k.startsWith(P()))localStorage.setItem(k,v)}); msg('Yedek geri yüklendi.'); render()}catch(e){msg('Yedek okunamadı.')}}; r.readAsText(f,'utf-8')};
window.lexSaveBackupUrlV8=function(){localStorage.setItem(P()+'backupUrlV8',$('v8BackupUrl')?.value||''); msg('Yedek bağlantısı kaydedildi.')};
window.lexImportBackupUrlV8=async function(){const url=$('v8BackupUrl')?.value||localStorage.getItem(P()+'backupUrlV8')||''; if(!url)return msg('Yedek bağlantısı yok.'); try{let t=''; for(const u of [url,'https://api.allorigins.win/raw?url='+encodeURIComponent(url)]){try{const r=await fetch(u,{cache:'no-store'}); if(r.ok){t=await r.text();break}}catch(e){}} const d=JSON.parse(t); Object.entries(d.localStorage||{}).forEach(([k,v])=>{if(k.startsWith(P()))localStorage.setItem(k,v)}); msg('Bulut yedeği geri yüklendi.'); render()}catch(e){msg('Bulut yedeği alınamadı: '+(e.message||e))}};

/* -------- Arabic pronunciation / TTS layer -------- */
function arabicPhoneticV8(s){
 let x=String(s||'');
 const pairs=[
  [/Bismi\s*el-?lâhi\s*er-?rahmâni\s*er-?rahîmi/gi,'Bismillahirrahmanirrahim'],
  [/Bismillâhirrahmânirrahîm/gi,'Bismillahirrahmanirrahim'],
  [/el-?lâh/gi,'Allah'],[/Allâh/gi,'Allah'],[/er-?rahmân/gi,'irrahman'],[/er-?rahîm/gi,'irrahim'],
  [/Sûresi/gi,'Suresi'],[/Yâsîn/gi,'Yasin'],[/Fetîh/gi,'Fetih'],[/rahmân/gi,'rahman'],[/rahîm/gi,'rahim'],
  [/â/g,'a'],[/î/g,'i'],[/û/g,'u'],[/ý/g,'ı'],[/þ/g,'ş'],[/ð/g,'ğ']
 ];
 pairs.forEach(([a,b])=>x=x.replace(a,b));
 return x.replace(/\s+/g,' ').trim();
}
function hasArabic(s){return /[\u0600-\u06FF]/.test(String(s||''))}
function browserArabicVoice(){try{return (speechSynthesis.getVoices()||[]).find(v=>/^ar/i.test(v.lang||''))}catch(e){return null}}
window.speakArabicSafe=function(encodedArabic,encodedRead,key,btn){
 const ar=dec(encodedArabic||''), rd=arabicPhoneticV8(dec(encodedRead||'')); const text=ar||rd;
 try{if(window.currentAudioKey===key||btn?.classList.contains('playing')){if(window.stopAudio)stopAudio(); if(window.speechSynthesis)speechSynthesis.cancel(); return}}catch(e){}
 if(hasArabic(ar)){
   try{if(window.AndroidBridge&&AndroidBridge.speak){AndroidBridge.speak(ar,'ar-SA'); return}}catch(e){}
   try{const v=browserArabicVoice(); if(v&&'speechSynthesis' in window){const u=new SpeechSynthesisUtterance(ar); u.lang='ar-SA'; u.voice=v; u.rate=.82; speechSynthesis.cancel(); speechSynthesis.speak(u); return}}catch(e){}
 }
 if(rd){try{if(window.speak)speak(rd,'tr-TR',key,btn); else {const u=new SpeechSynthesisUtterance(rd); u.lang='tr-TR'; speechSynthesis.cancel(); speechSynthesis.speak(u)}}catch(e){}}
};
function normalizeArabicDomV8(){document.querySelectorAll('.phonetic,.readPron,.value,.line').forEach(el=>{if(el.dataset.v8phon)return; const t=el.textContent||''; const n=arabicPhoneticV8(t); if(n&&n!==t&&/Bismi|Allâh|rahm|ý|þ|ð/.test(t)){el.textContent=n; el.dataset.v8phon='1'}})}

/* -------- Route wrapping and global stop events -------- */
const oldRenderV8=window.render;
let lastRouteV8='';
window.render=function(){
 cssV8(); installCategoriesV8();
 const route=modeNow()+'|'+catNow(); if(lastRouteV8&&lastRouteV8!==route)window.lexStopAllMediaV8(); lastRouteV8=route;
 if(modeNow()==='read'&&catNow()===catAudio()){setCatRead(QURAN_CAT)}
 if(modeNow()==='read'&&catNow()===catNews())return renderNewsReadV8();
 const r=oldRenderV8?oldRenderV8.apply(this,arguments):undefined;
 setTimeout(()=>{try{renderAudioPanelV8(); appendBackupPanelV8(); patchGrammarDomV8(); normalizeArabicDomV8()}catch(e){console.error('v8 post',e)}},80);
 return r;
};
