window.renderWrite=function(){const x=current(); if(!x)return; const tasks=writeTasks(x), ti=Number(window.__v9WriteTask||0)%tasks.length, t=tasks[ti]; let html=`<section class="${modClass()} v9Write"><span class="badge">Yazma • ${catName(settings.cat)} • görev ${ti+1}/${tasks.length}</span><h3>${safeEsc(t.title)}</h3><div class="hint">Profesyonel yazma çalışması: anlam, dikte, cümle kurma, çeviri ve boşluk doldurma aynı kartı farklı becerilerle ölçer.</div><div class="v9Prompt">${safeEsc(t.prompt)}</div>`; if(t.audio)html+=`<button class="ghost" onclick="speakSafe('${safeEnc(t.audio)}','nl-NL','v9dict',this)">🔊 Dikteyi dinle</button>`; if(t.contains)html+=`<textarea id="v9WriteFree" placeholder="Hollandaca cümleni yaz"></textarea>`; else (t.fields||[]).forEach((f,i)=>{html+=`<input id="v9Ans${i}" placeholder="${safeEsc(f[0])}">`}); html+=`<div class="row3"><button class="ghost" onclick="v9WriteTaskPrev()">‹ Görev</button><button onclick="v9CheckWrite()">Kontrol et</button><button class="ghost" onclick="v9WriteTaskNext()">Görev ›</button></div><div id="writeResult" class="note"></div><div class="row3"><button class="ghost" onclick="newQuiz&&newQuiz('choice'); setMode('quiz')">Quiz</button><button class="ghost" onclick="newQuiz&&newQuiz('listen'); setMode('quiz')">Dinleme</button><button class="ghost" onclick="newQuiz&&newQuiz('pronounce'); setMode('quiz')">Telaffuz</button></div>${moduleNav()}</section>`; $v('view').innerHTML=html;};
window.v9CheckWrite=function(){const x=current(), tasks=writeTasks(x), t=tasks[Number(window.__v9WriteTask||0)%tasks.length]; let ok=false,out=[]; if(t.contains){const got=$v('v9WriteFree')?.value||''; ok=normalize(got).includes(normalize(t.contains))&&got.trim().split(/\s+/).length>=4; out.push(ok?'✅ Kelimeyi anlamlı cümlede kullandınız.':'❌ Cümlede hedef kelime bulunmalı ve cümle en az 4 kelime olmalı.');} else (t.fields||[]).forEach((f,i)=>{const got=$v('v9Ans'+i)?.value||'', exp=f[1]||''; const good=normalize(got)===normalize(exp)||normalize(got).includes(normalize(exp)); if(good)ok=true; out.push(`${safeEsc(f[0])}: ${good?'✅ Doğru':'❌ Beklenen: '+safeEsc(exp)}`)}); $v('writeResult').innerHTML=out.join('<br>'); if(ok){try{addQuizPoint?addQuizPoint('yazma'):markQuizScore&&markQuizScore('yazma')}catch(e){}}};
