function buildTabsV9(){const tabs=document.querySelector('.tabsInner'); if(!tabs)return; const html=`<button class="tabBtn" id="tabLearn" onclick="setMode('learn')"><span class="tabIcon">▣</span><span>Kart</span></button><button class="tabBtn" id="tabWrite" onclick="setMode('write')"><span class="tabIcon">✎</span><span>Yazma</span></button><button class="tabBtn" id="tabRead" onclick="setMode('read')"><span class="tabIcon">📖</span><span>Okuma</span></button><button class="tabBtn" id="tabGrammar" onclick="setMode('grammar')"><span class="tabIcon">Ω</span><span>Gramer</span></button><button class="tabBtn" id="tabList" onclick="setMode('list')"><span class="tabIcon">☷</span><span>Liste</span></button><button class="tabBtn" id="tabEbook" onclick="setMode('ebook')"><span class="tabIcon">📚</span><span>E-kitap</span></button><button class="tabBtn" id="tabAvOfis" onclick="setMode('avofis')"><span class="tabIcon">⚖</span><span>AvOfis</span></button>`; if(tabs.dataset.v9!=='1'||tabs.innerHTML.indexOf('tabSentences')>=0){tabs.innerHTML=html; tabs.dataset.v9='1';}}
