function v10HasArabic(s){return /[\u0600-\u06FF]/.test(String(s||''))}
function v10ArabicLatin(txt){
  const m={'ا':'a','أ':'a','إ':'i','آ':'aa','ٱ':'a','ب':'b','ت':'t','ث':'s','ج':'c','ح':'h','خ':'kh','د':'d','ذ':'z','ر':'r','ز':'z','س':'s','ش':'ş','ص':'s','ض':'d','ط':'t','ظ':'z','ع':'a','غ':'ğ','ف':'f','ق':'q','ك':'k','ک':'k','ل':'l','م':'m','ن':'n','ه':'h','ة':'a','و':'v','ؤ':'u','ي':'y','ى':'a','ئ':'i','ء':'','َ':'a','ِ':'i','ُ':'u','ً':'an','ٍ':'in','ٌ':'un','ْ':'','ّ':'','ٰ':'aa','ـ':'','ٓ':'','ٰ':'aa'};
  let out=String(txt||'').replace(/[\u0600-\u06FF]/g,ch=>m[ch]!==undefined?m[ch]:'');
  return out.replace(/Allah/ig,'Allah').replace(/\s+/g,' ').replace(/([a-z])aa/gi,'$1aa').trim();
}
